(window.CARDS = window.CARDS || {}).series = [{"name":"Игра престолов","emoji":"🐉","meta":["драма, фэнтези","2011–2019","США"],"description":"Эпическая экранизация цикла романов Джорджа Мартина о войне знатных домов за Железный трон Вестероса. HBO объединили в сериале политические интриги, масштабные сражения и мифологию с драконами и угрозой из-за Стены. На пике популярности сериал собирал у экранов десятки миллионов зрителей по всему миру.","fact":"Финальный сезон вызвал волну петиций от разочарованных зрителей с требованием переснять концовку заново.","wiki_en":"Game of Thrones"},{"name":"Во все тяжкие","emoji":"🧪","meta":["драма, криминал","2008–2013","США"],"description":"История школьного учителя химии, который после диагноза «рак» начинает готовить метамфетамин, чтобы обеспечить семью, и постепенно превращается в безжалостного криминального авторитета. Сериал славится продуманной драматургией и постепенным перерождением главного героя.","fact":"Создатель сериала Винс Гиллиган описывал его идею как превращение мистера Чипса в Скарфейса.","wiki_en":"Breaking Bad"},{"name":"Друзья","emoji":"☕","meta":["ситком","1994–2004","США"],"description":"Ситком о шестерых друзьях, которые живут по соседству в Нью-Йорке и вместе проходят через работу, отношения и взросление. Львиная доля действия происходит в квартирах героев и кофейне Central Perk, ставшей одним из самых узнаваемых мест на телевидении.","fact":"Актёры настояли на равной оплате друг другу и в поздних сезонах получали по миллиону долларов за серию каждый.","wiki_en":"Friends"},{"name":"Офис","emoji":"📎","meta":["мокьюментари, комедия","2005–2013","США"],"description":"Американская адаптация британского ситкома в формате псевдодокументалистики о буднях сотрудников захолустной бумажной компании Dunder Mifflin. Съёмочная группа якобы снимает документальный фильм, а герои то и дело обращаются прямо в камеру.","fact":"Сериал начинался как почти дословный ремейк британского оригинала, но со второго сезона обрёл собственный тон и стал самостоятельным явлением.","wiki_en":"The Office (American TV series)"},{"name":"Симпсоны","emoji":"🍩","meta":["мультсериал, комедия","с 1989","США"],"description":"Мультсериал о жёлтолицей семье из вымышленного города Спрингфилд, который сатирически высмеивает американский быт, поп-культуру и политику. Идёт дольше любого другого прайм-таймового сериала в истории американского телевидения.","fact":"Многие сюжетные повороты «Симпсонов» позже неожиданно сбывались в реальности, что породило целый интернет-миф о его предсказаниях.","wiki_en":"The Simpsons"},{"name":"Южный Парк","emoji":"🏔️","meta":["мультсериал, комедия","с 1997","США"],"description":"Скандальный мультсериал о четырёх мальчишках из маленького горного городка в Колорадо, который высмеивает актуальные новости и общественные табу почти без фильтров. Эпизоды часто пишутся и монтируются буквально за несколько дней до эфира, чтобы успеть за повесткой.","fact":"Один из главных героев, Кенни, регулярно погибает в каждой серии ранних сезонов и неизменно возвращается целым и невредимым в следующей.","wiki_en":"South Park"},{"name":"Гриффины","emoji":"🐶","meta":["мультсериал, комедия","с 1999","США"],"description":"Мультсериал о нелепой семье Гриффин из вымышленного городка Куахог, где происходящее то и дело прерывается абсурдными отступлениями и пародийными флешбэками. Создатель Сет Макфарлейн озвучивает сразу нескольких ключевых персонажей, включая говорящего пса Брайана.","fact":"После отмены из-за низких рейтингов в начале 2000-х сериал был возвращён в эфир во многом благодаря бешеной популярности повторов и продаж DVD.","wiki_en":"Family Guy"},{"name":"Рик и Морти","emoji":"🌀","meta":["мультсериал, фантастика","с 2013","США"],"description":"Мультсериал о гениальном и циничном учёном-алкоголике Рике и его тревожном внуке Морти, которые путешествуют между бесчисленными измерениями и мирами. Под слоем безумного юмора и научной фантастики скрываются размышления о смысле существования и семейных отношениях.","fact":"Боевой клич Рика Wubba lubba dub dub его друг Птичья Персона переводит куда печальнее: «мне очень больно, пожалуйста, помогите».","wiki_en":"Rick and Morty"},{"name":"Футурама","emoji":"🚀","meta":["мультсериал, фантастика","с 1999, с перерывами","США"],"description":"Мультсериал от создателя «Симпсонов» Мэтта Грейнинга о курьере Фрае, который замерзает в криокапсуле в 1999 году и просыпается тысячу лет спустя в причудливом будущем. Вместе с экипажем звездолёта доставки он попадает в приключения по всей галактике.","fact":"Несмотря на несколько отмен и закрытий, сериал неоднократно возвращался благодаря фильмам, новым сезонам и стриминговым перезапускам.","wiki_en":"Futurama"},{"name":"Очень странные дела","emoji":"💡","meta":["фантастика, ужасы","с 2016","США"],"description":"Ностальгическая по восьмидесятым история о компании подростков из маленького городка Хокинс, где после исчезновения мальчика начинают происходить сверхъестественные события. Сериал переплетает подростковую дружбу с мифологией параллельного мира — Изнанки.","fact":"Сериал сделал звёздами почти неизвестных до него детей-актёров и заодно вернул на первый план Вайнону Райдер, звезду кино 1990-х.","wiki_en":"Stranger Things"},{"name":"Клан Сопрано","emoji":"🍝","meta":["драма, криминал","1999–2007","США"],"description":"Драма о боссе итало-американской мафии из Нью-Джерси, который параллельно с криминальными делами ходит на сеансы к психотерапевту, пытаясь справиться с паническими атаками. Сериал во многом задал стандарт для современной «престижной» телевизионной драмы.","fact":"Финальная сцена в закусочной, которая обрывается внезапным затемнением прямо под играющую песню, до сих пор остаётся предметом споров.","wiki_en":"The Sopranos"},{"name":"Прослушка","emoji":"🎧","meta":["драма, криминал","2002–2008","США"],"description":"Многослойная драма о Балтиморе, которая через прослушку телефонов наркоторговцев показывает город со всех сторон — от полиции и портовых докеров до школ, политиков и прессы. Каждый сезон переключает фокус на новый институт городской жизни.","fact":"Сериал не получил ни одной награды «Эмми» во время оригинального эфира, хотя критики регулярно называют его одним из лучших в истории телевидения.","wiki_en":"The Wire"},{"name":"Шерлок","emoji":"🔍","meta":["детектив, драма","2010–2017","Великобритания"],"description":"Современная британская интерпретация историй Артура Конан Дойля, где Шерлок Холмс и доктор Ватсон действуют в сегодняшнем Лондоне со смартфонами и соцсетями вместо телеграмм. Сериал известен стремительным темпом и визуализацией хода мыслей детектива прямо на экране.","fact":"Из-за плотных графиков актёров сериал выходит очень короткими сезонами по три полнометражных эпизода, а перерывы между сезонами растягивались на годы.","wiki_en":"Sherlock (TV series)"},{"name":"Доктор Хаус","emoji":"🩺","meta":["драма","2004–2012","США"],"description":"Медицинская драма о блестящем, но крайне неуживчивом диагносте докторе Хаусе, который вместе с командой врачей распутывает самые загадочные и редкие случаи болезней. Герой славится циничными репликами и правилом, что пациенты всегда лгут.","fact":"Образ Хауса создатели сериала прямо вдохновили детективом Шерлоком Холмсом, вплоть до адреса квартиры и верного друга-помощника.","wiki_en":"House (TV series)"},{"name":"Остаться в живых","emoji":"🏝️","meta":["драма, фантастика","2004–2010","США"],"description":"После крушения самолёта группа выживших пассажиров оказывается на таинственном тропическом острове, где происходят необъяснимые события. Сериал сочетает драму отношений между героями с мифологией острова, раскрывающейся через флешбэки.","fact":"Сериал одним из первых массово использовал нелинейные флешбэки и флешфорварды как основной инструмент повествования на телевидении.","wiki_en":"Lost (TV series)"},{"name":"Побег","emoji":"⛓️","meta":["драма, триллер","2005–2009","США"],"description":"Инженер Майкл Скофилд специально идёт на преступление, чтобы попасть в тюрьму, где несправедливо осуждён его брат, и вытатуировывает на теле план побега. Сериал построен вокруг напряжённой подготовки и исполнения дерзкого тюремного побега.","fact":"Огромную татуировку-карту актёру не набивали, а наносили гримёры переводными деталями — процедура занимала по несколько часов.","wiki_en":"Prison Break"},{"name":"Декстер","emoji":"🔪","meta":["драма, триллер","2006–2013","США"],"description":"Судебный эксперт по анализу крови Декстер Морган днём помогает полиции Майами раскрывать убийства, а по ночам сам убивает преступников, следуя строгому «кодексу» приёмного отца. Сериал держится на закадровых размышлениях героя о собственной двойной жизни.","fact":"Главную роль сыграл Майкл Си Холл, до этого известный по другому необычному сериалу о смерти — «Клиент всегда мёртв».","wiki_en":"Dexter (TV series)"},{"name":"Ходячие мертвецы","emoji":"🧟","meta":["ужасы, драма","2010–2022","США"],"description":"Экранизация комиксов о шерифе Рике Граймсе, который приходит в себя после комы в мире, захваченном зомби-эпидемией, и собирает вокруг себя группу выживших. По ходу сериала акцент смещается с самих зомби на противостояние разных человеческих группировок.","fact":"Долгое время сериал был самым популярным шоу на кабельном телевидении США среди зрителей до 49 лет.","wiki_en":"The Walking Dead (TV series)"},{"name":"Теория Большого взрыва","emoji":"🤓","meta":["ситком","2007–2019","США"],"description":"Ситком о компании учёных-физиков из Калтеха, чья жизнь строится вокруг науки, комиксов и видеоигр, пока в доме напротив не поселяется симпатичная официантка Пенни. Юмор строится на контрасте между гениальностью героев в науке и их неловкостью в обычном общении.","fact":"Формулы на досках в кадре для достоверности писал приглашённый консультант — физик из Калифорнийского университета.","wiki_en":"The Big Bang Theory"},{"name":"Как я встретил вашу маму","emoji":"☂️","meta":["ситком","2005–2014","США"],"description":"Тед Мосби из будущего рассказывает своим детям долгую и запутанную историю о том, как он познакомился с их мамой, попутно вспоминая годы дружбы, любви и приключений с четырьмя близкими друзьями в Нью-Йорке. Ключевую роль в компании играет эксцентричный обаятельный Барни.","fact":"Саму маму зрители впервые видят только к финалу восьмого сезона, а до этого о ней намекают деталями вроде жёлтого зонтика.","wiki_en":"How I Met Your Mother"},{"name":"Клиника","emoji":"🏥","meta":["ситком","2001–2010","США"],"description":"Комедийный сериал о буднях молодого врача Джей Ди в вымышленной больнице Сэйкред Харт, где абсурдный юмор соседствует с неожиданно серьёзными и трогательными медицинскими сюжетами. Значительная часть шуток строится на фантазиях главного героя, которые зритель видит прямо на экране.","fact":"Многие сюжеты сериала основаны на реальных историях, которые сценаристам рассказывал консультант-врач, работавший в настоящей больнице.","wiki_en":"Scrubs (2001 TV series)"},{"name":"Секс в большом городе","emoji":"👠","meta":["комедия, драма","1998–2004","США"],"description":"Колумнистка Кэрри Брэдшоу и три её близкие подруги живут насыщенной жизнью в Нью-Йорке, обсуждая любовь, карьеру и секс за бокалом коктейлей «Космополитан». Каждая серия строится вокруг колонки, которую Кэрри пишет о современных отношениях.","fact":"Гардероб героинь, включая знаменитые туфли Маноло Бланик, сам по себе стал важной частью культурного наследия сериала.","wiki_en":"Sex and the City"},{"name":"Отчаянные домохозяйки","emoji":"🏡","meta":["драма, комедия","2004–2012","США"],"description":"Жизнь нескольких домохозяек на тихой улочке Вистерия-Лейн, полной секретов, измен и преступлений, показана глазами их соседки, покончившей с собой в первой серии и комментирующей события из-за кадра. Сериал сочетает мыльную оперу с чёрным юмором и детективной интригой.","fact":"Идея сериала пришла его создателю после того, как он посмотрел выпуск новостей о матери, которая утопила своих детей.","wiki_en":"Desperate Housewives"},{"name":"Сплетница","emoji":"💌","meta":["драма","2007–2012","США"],"description":"Жизнь избалованных подростков с Верхнего Ист-Сайда Манхэттена показана через анонимные сообщения таинственного блогера-сплетницы, который знает обо всех тайнах, изменах и скандалах привилегированной молодёжи. Каждый эпизод сопровождается её закадровыми репликами.","fact":"Закадровый голос Сплетницы принадлежит актрисе Кристен Белл, а личность самого автора блога раскрывают только в финальной серии.","wiki_en":"Gossip Girl"},{"name":"Анатомия страсти","emoji":"❤️‍🩹","meta":["драма","с 2005","США"],"description":"Медицинская драма о хирургах-ординаторах больницы Сиэтл Грейс, чья профессиональная жизнь неотделима от запутанных личных отношений и романов друг с другом. Сериал известен закадровыми монологами главной героини Мередит Грей и стал одним из самых долгоживущих драматических шоу США.","fact":"Название сериала обыгрывает старинный медицинский трактат по анатомии, которым пользовалось не одно поколение врачей.","wiki_en":"Grey's Anatomy"},{"name":"Секретные материалы","emoji":"👽","meta":["фантастика, детектив","1993–2018","США"],"description":"Агенты ФБР Малдер и Скалли расследуют дела, связанные с паранормальными явлениями, инопланетянами и правительственными заговорами, при этом герой верит в необъяснимое, а его напарница-скептик ищет рациональные объяснения. Сериал во многом определил жанр телевизионного мистического детектива девяностых.","fact":"Слоган сериала «Истина где-то рядом» стал крылатой фразой далеко за пределами телевидения.","wiki_en":"The X-Files"},{"name":"Твин Пикс","emoji":"🪵","meta":["детектив, мистика","1990–1991","США"],"description":"Расследование убийства школьницы Лоры Палмер приводит агента ФБР Дейла Купера в маленький городок Твин-Пикс, где за фасадом уютной провинции скрываются сюрреалистичные тайны и потусторонние силы. Сериал Дэвида Линча совместил детективный сюжет с атмосферой сновидения.","fact":"Знаменитая фраза «Совы не то, чем они кажутся» стала одним из главных символов загадочной мифологии сериала.","wiki_en":"Twin Peaks"},{"name":"Настоящий детектив","emoji":"🥃","meta":["детектив, драма","с 2014","США"],"description":"Антологический сериал, где каждый сезон рассказывает отдельную мрачную детективную историю с новыми героями и актёрами. Первый и самый известный сезон следит за двумя напарниками-детективами, которые на протяжении почти двадцати лет расследуют серию ритуальных убийств в Луизиане.","fact":"Шестиминутная сцена в четвёртом эпизоде первого сезона снята одним непрерывным кадром и стала одной из самых обсуждаемых на телевидении.","wiki_en":"True Detective"},{"name":"Чёрное зеркало","emoji":"📱","meta":["фантастика, драма","с 2011","Великобритания"],"description":"Антологический сериал, где почти каждая серия — самостоятельная мрачная притча о том, как современные технологии способны исказить человеческие отношения и общество. Название отсылает к тёмному экрану гаджета, в который мы вглядываемся, как в зеркало.","fact":"Один из эпизодов сериала был интерактивным фильмом «Брандашмыг», где зритель сам выбирал развитие сюжета.","wiki_en":"Black Mirror"},{"name":"Острые козырьки","emoji":"🎩","meta":["драма, криминал","2013–2022","Великобритания"],"description":"История бирмингемской криминальной семьи Шелби, которая после Первой мировой войны выстраивает собственную преступную империю под руководством харизматичного и расчётливого Томаса Шелби. Название отсылает к легенде, будто члены банды прятали бритвенные лезвия в козырьках кепок.","fact":"Хотя действие происходит в начале двадцатого века, саундтрек сериала почти целиком построен на современной рок- и электронной музыке.","wiki_en":"Peaky Blinders (TV series)"},{"name":"Викинги","emoji":"⚔️","meta":["драма, история","2013–2020","Канада"],"description":"Полулегендарная история скандинавского вождя Рагнара Лодброка, который поднимает своих соплеменников на дерзкие морские походы в Западную Европу. Сериал вольно опирается на скандинавские саги и хроники, смешивая исторические события с мифологией.","fact":"Многие диалоги в сериале звучат на древнескандинавском и староанглийском языках с субтитрами для достоверности эпохи.","wiki_en":"Vikings (2013 TV series)"},{"name":"Ведьмак","emoji":"🐺","meta":["фэнтези, драма","с 2019","США"],"description":"Экранизация книжного цикла Анджея Сапковского о ведьмаке Геральте из Ривии — наёмном охотнике на чудовищ, чей путь переплетается с судьбами чародейки Йеннифэр и принцессы Цири. Сериал сочетает мрачное фэнтези с политическими интригами враждующих королевств.","fact":"Генри Кавилл — большой фанат книг и игр о ведьмаке, и для роли он снимался в белом парике и жёлтых контактных линзах.","wiki_en":"The Witcher (TV series)"},{"name":"Мандалорец","emoji":"🪖","meta":["фантастика","с 2019","США"],"description":"Одинокий охотник за головами в стальной броне из вселенной «Звёздных войн» берёт под защиту загадочного малыша своего вида и отправляется в опасное путешествие через окраины галактики. Сериал возродил дух вестерна на далёкой периферии знакомой саги.","fact":"Милого зелёного персонажа-малыша, которого фанаты прозвали «Бэби Йода», студия официально не называла по имени до второго сезона.","wiki_en":"The Mandalorian"},{"name":"Одни из нас","emoji":"🍄","meta":["драма, ужасы","с 2023","США"],"description":"Экранизация видеоигры о контрабандисте Джоэле, который берётся сопроводить через опустошённую грибковой пандемией Америку девочку-подростка Элли, возможно, хранящую ключ к спасению человечества. Сериал делает акцент на драме отношений героев не меньше, чем на выживании среди заражённых.","fact":"Сценарий сериала во многом писали создатели оригинальной игры, что позволило сохранить сюжет и характеры почти без изменений.","wiki_en":"The Last of Us (TV series)"},{"name":"Чернобыль","emoji":"☢️","meta":["драма, история","2019","США, Великобритания"],"description":"Минисериал о катастрофе на Чернобыльской атомной электростанции в 1986 году и её последствиях для ликвидаторов, учёных и жителей близлежащих городов. Создатели воссоздали советский быт и атмосферу эпохи с большим вниманием к деталям.","fact":"Для съёмок сериала многие интерьеры и улицы воссоздавали в Литве, где сохранилась советская архитектура похожего стиля.","wiki_en":"Chernobyl (miniseries)"},{"name":"Корона","emoji":"👑","meta":["драма, история","2016–2023","Великобритания"],"description":"Драма прослеживает жизнь британской королевы Елизаветы Второй и её семьи от восшествия на престол в начале пятидесятых до недавних десятилетий, показывая закулисье монархии на фоне больших исторических событий. Через несколько сезонов основной актёрский состав полностью меняется, чтобы соответствовать возрасту героев.","fact":"Ради исторической достоверности создатели воссоздавали костюмы и интерьеры по архивным фотографиям и подлинным королевским нарядам.","wiki_en":"The Crown (TV series)"},{"name":"Бумажный дом","emoji":"🎭","meta":["драма, криминал","2017–2021","Испания"],"description":"Группа грабителей под руководством загадочного Профессора устраивает дерзкий захват Королевского монетного двора Испании, чтобы напечатать миллиарды евро изнутри, а не украсть их. Все участники банды берут себе имена городов, а маски в стиле Сальвадора Дали стали визитной карточкой сериала.","fact":"Испанский сериал стал одним из самых просматриваемых неанглоязычных проектов Netflix во всём мире.","wiki_en":"Money Heist"},{"name":"Игра в кальмара","emoji":"🦑","meta":["драма, триллер","2021","Южная Корея"],"description":"Сотни людей, погрязших в долгах, соглашаются участвовать в серии смертельно опасных детских игр ради огромного денежного приза. За соревнованием тайно наблюдают богатые зрители, для которых чужое отчаяние превращается в развлечение.","fact":"Сериал стал самым просматриваемым проектом за всю историю Netflix на момент выхода.","wiki_en":"Squid Game"},{"name":"Нарко","emoji":"🌿","meta":["драма, криминал","2015–2017","США"],"description":"Сериал реконструирует историю противостояния колумбийских наркокартелей и правительственных агентов США, в центре которой — восхождение и падение печально известного наркобарона Пабло Эскобара. Повествование сочетает документальные архивные кадры с драматизированными сценами.","fact":"Часть сериала снималась непосредственно в Колумбии, а некоторые локации связаны с реальными событиями из жизни картеля.","wiki_en":"Narcos"},{"name":"Озарк","emoji":"💵","meta":["драма, криминал","2017–2022","США"],"description":"Финансовый консультант Марти Бёрд вынужден с семьёй переехать в курортный регион Озарк, чтобы отмывать деньги для мексиканского наркокартеля и расплатиться с долгами. Сериал показывает, как благополучная с виду семья постепенно погружается в криминальный мир.","fact":"Название отсылает к реальному региону Озарк на стыке Миссури и Арканзаса, где по сюжету и разворачивается почти всё действие.","wiki_en":"Ozark (TV series)"},{"name":"Лучше звоните Солу","emoji":"⚖️","meta":["драма, криминал","2015–2022","США"],"description":"Приквел «Во все тяжкие» рассказывает историю адвоката Джимми Макгилла, который постепенно превращается в изворотливого юриста-мошенника Сола Гудмана. Сериал детально показывает моральное падение героя задолго до событий основного шоу.","fact":"Многие критики называют этот приквел равным или даже превосходящим по драматургии оригинальный сериал «Во все тяжкие».","wiki_en":"Better Call Saul"},{"name":"Безумцы","emoji":"🥃","meta":["драма","2007–2015","США"],"description":"Драма о сотрудниках рекламного агентства на Мэдисон-авеню в Нью-Йорке начала шестидесятых, в центре которой — харизматичный, но закрытый креативный директор Дон Дрейпер. Сериал славится дотошным воссозданием моды, интерьеров и нравов той эпохи.","fact":"По утверждению создателей, Mad Men — сленговое прозвище, которым рекламщики с Мэдисон-авеню называли сами себя.","wiki_en":"Mad Men"},{"name":"Карточный домик","emoji":"🃏","meta":["драма","2013–2018","США"],"description":"Циничный конгрессмен Фрэнк Андервуд, обойдённый обещанным назначением, начинает беспощадную интригу по восхождению к вершинам американской власти, время от времени обращаясь напрямую к зрителю. Сериал стал одним из первых крупных оригинальных проектов Netflix.","fact":"Американская версия — ремейк британского мини-сериала 1990 года, снятого по роману Майкла Доббса.","wiki_en":"House of Cards (American TV series)"},{"name":"Наследники","emoji":"💼","meta":["драма, чёрная комедия","2018–2023","США"],"description":"Сатирическая драма о медиамагнате Логане Рое и его взрослых детях, которые плетут интриги и грызутся между собой за право унаследовать его глобальную медиаимперию. Сериал беспощадно высмеивает нравы сверхбогатых и корпоративную борьбу за власть.","fact":"Сценарий во многом вдохновлён реальными медиадинастиями, хотя создатели всегда подчёркивали, что персонажи вымышлены.","wiki_en":"Succession (TV series)"},{"name":"Белый лотос","emoji":"🌺","meta":["чёрная комедия, драма","с 2021","США"],"description":"Антологический сериал, каждый сезон которого разворачивается в новом роскошном отеле сети «Белый лотос» и следит за постояльцами и персоналом, чьи скрытые пороки и конфликты постепенно выходят наружу. С первых минут сезона зрителю известно, что кто-то из героев погибнет.","fact":"Первый сезон снимали на Гавайях в настоящем курортном отеле, где во время съёмок жила и вся съёмочная группа.","wiki_en":"The White Lotus"},{"name":"Эйфория","emoji":"💊","meta":["драма","с 2019","США"],"description":"Сериал показывает жизнь группы американских старшеклассников через призму зависимостей, поиска идентичности и первой любви, часто прибегая к ярким визуальным приёмам и закадровым монологам героини Ру. Тема наркозависимости раскрывается без прикрас и смягчения.","fact":"Яркий макияж с блёстками, который носят героини сериала, спровоцировал отдельный модный тренд, получивший собственное название.","wiki_en":"Euphoria (American TV series)"},{"name":"Уэнздей","emoji":"🖤","meta":["комедия, ужасы","с 2022","США"],"description":"Дочь семейки Аддамс Уэнздей поступает в мрачную академию для изгоев Невермор, где ей приходится раскрывать сверхъестественную тайну, заводить первых в жизни друзей и разбираться с собственными паранормальными способностями. Сериал сочетает готическую эстетику с подростковой комедией.","fact":"Танец, который героиня исполняет на школьном балу, был во многом придуман самой актрисой и стал вирусным в соцсетях по всему миру.","wiki_en":"Wednesday (TV series)"},{"name":"Бриджертоны","emoji":"💍","meta":["драма, романтика","с 2020","США"],"description":"Экранизация романов Джулии Куин о большом семействе Бриджертонов в лондонском высшем свете эпохи Регентства, где каждый сезон в центре внимания оказывается любовная история одного из братьев или сестёр. За скандалами и слухами светского общества незримо следит анонимная сплетница леди Уислдаун.","fact":"В сериале, в отличие от классических костюмных драм, актёрский состав подчёркнуто мультирасовый, что стало предметом широкого обсуждения.","wiki_en":"Bridgerton"},{"name":"Ход королевы","emoji":"♟️","meta":["драма","2020","США"],"description":"Минисериал о юной шахматной вундеркинде Бет Хармон, которая растёт в приюте, борется с зависимостью от успокоительных и постепенно пробивается к вершинам мужского по большей части шахматного мира. Сериал показывает шахматные партии почти так же напряжённо, как спортивные поединки.","fact":"После выхода сериала во всём мире резко вырос интерес к шахматам, включая продажи шахматных досок и записи на уроки игры.","wiki_en":"The Queen's Gambit (miniseries)"},{"name":"Тед Лассо","emoji":"⚽","meta":["комедия, спорт","2020–2023","США"],"description":"Американский тренер по американскому футболу без всякого опыта в европейском футболе неожиданно возглавляет английский клуб и покоряет скептически настроенную команду неизменным оптимизмом и добротой. Сериал прославился тёплым, почти терапевтическим тоном в противовес циничным комедиям.","fact":"Персонаж Теда Лассо впервые появился ещё в рекламных роликах канала NBC про английскую Премьер-лигу за несколько лет до сериала.","wiki_en":"Ted Lasso"},{"name":"Медведь","emoji":"🐻","meta":["драма, комедия","с 2022","США"],"description":"Молодой шеф-повар высокой кухни возвращается в родной Чикаго, чтобы взять на себя семейную закусочную после смерти брата, и пытается навести порядок среди хаоса кухни и собственных травм. Сериал известен напряжёнными, почти документальными сценами работы ресторанной кухни.","fact":"Один из самых обсуждаемых эпизодов сделан так, будто снят одним непрерывным кадром, — это до предела усиливает ощущение кухонного хаоса.","wiki_en":"The Bear (TV series)"},{"name":"Разделение","emoji":"🧠","meta":["фантастика, триллер","с 2022","США"],"description":"Сотрудники загадочной корпорации проходят процедуру «разделения», которая буквально раскалывает их сознание на рабочую и повседневную личности, не помнящие друг о друге. Сериал строит напряжённую антиутопию вокруг вопросов идентичности и контроля корпорации над жизнью человека.","fact":"Внешние виды и холл корпорации снимали в реальном модернистском здании бывших исследовательских лабораторий в Нью-Джерси.","wiki_en":"Severance (TV series)"},{"name":"Пацаны","emoji":"🦸","meta":["фантастика, чёрная комедия","с 2019","США"],"description":"В мире, где супергерои — это продукт корпорации, зарабатывающей на их культе, группа обычных людей мстит продажным и жестоким «героям» за причинённый ими вред. Сериал беспощадно пародирует супергеройский жанр и высмеивает индустрию медиа-культов.","fact":"Многие персонажи сериала — узнаваемые пародии на культовых супергероев из комиксов известных издательств.","wiki_en":"The Boys (TV series)"},{"name":"Дом Дракона","emoji":"🐲","meta":["фэнтези, драма","с 2022","США"],"description":"Приквел «Игры престолов» разворачивается почти за двести лет до событий основного сериала и рассказывает о кровавой междоусобной войне за престол внутри дома Таргариенов, известной как «Танец драконов». Драконов здесь заметно больше, чем в основном сериале, и у каждого свой наездник из Таргариенов.","fact":"Основой сериала стала книга Джорджа Мартина «Пламя и кровь», написанная как псевдоисторическая хроника династии Таргариенов.","wiki_en":"House of the Dragon"},{"name":"Локи","emoji":"⚡","meta":["фантастика","с 2021","США"],"description":"После событий фильмов о Мстителях бог обмана Локи попадает в загадочное Управление Временными Изменениями, которое следит за целостностью временной линии, и вынужден сотрудничать с его агентами. Сериал стал первым в киновселенной Marvel, всерьёз затронувшим тему мультивселенной.","fact":"Локи Том Хиддлстон играет с самого первого «Тора» 2011 года — это одна из самых долгих ролей в киновселенной Marvel.","wiki_en":"Loki (TV series)"},{"name":"Аркейн","emoji":"💜","meta":["мультсериал, фэнтези","2021–2024","США"],"description":"Анимационный сериал по мотивам вселенной игры League of Legends рассказывает о двух сёстрах из разделённых на богатый и нищий кварталы города Пилтовера и Зауна, чьи пути расходятся из-за трагедии детства. Известен необычным, почти живописным стилем анимации.","fact":"Сериал делали около шести лет, и он стал одной из самых дорогих и технически сложных анимационных постановок своего времени.","wiki_en":"Arcane (TV series)"},{"name":"Аватар: Легенда об Аанге","emoji":"🌊","meta":["мультсериал, фэнтези","2005–2008","США"],"description":"Мультсериал о мире, разделённом на четыре народа, каждый из которых способен управлять одной из стихий, и о юном Аватаре Аанге, который должен овладеть всеми четырьмя стихиями и остановить войну Народа Огня. Сочетает восточную эстетику с проработанным взрослым сюжетом.","fact":"Создатели сериала консультировались с мастерами боевых искусств, чтобы каждый стиль владения стихией был основан на реальной технике.","wiki_en":"Avatar: The Last Airbender"},{"name":"Губка Боб Квадратные Штаны","emoji":"🧽","meta":["мультсериал, комедия","с 1999","США"],"description":"Мультсериал о неунывающей жёлтой морской губке в квадратных штанах, которая живёт в подводном городе Бикини Боттом, работает поваром в закусочной «Красти Краб» и постоянно попадает в нелепые ситуации вместе с друзьями. Стал одним из самых узнаваемых мультипликационных брендов в мире.","fact":"Создатель сериала Стивен Хилленбург до мультипликации работал морским биологом, что заметно повлияло на подводный сеттинг шоу.","wiki_en":"SpongeBob SquarePants"},{"name":"Наруто","emoji":"🍥","meta":["аниме","2002–2007","Япония"],"description":"Аниме о юном ниндзя Наруто Удзумаки, который мечтает стать самым сильным лидером своей деревни, несмотря на то что внутри него запечатан могучий демонический дух лисицы. Сериал прослеживает взросление героя, его дружбу и соперничество с товарищами по команде.","fact":"«Наруто» — это ещё и название спиральных ломтиков рыбного паштета для рамэна, а рамэн в сериале — любимая еда героя.","wiki_en":"Naruto"},{"name":"Ван-Пис","emoji":"🏴‍☠️","meta":["аниме","с 1999","Япония"],"description":"Аниме о молодом пирате Монки Д. Луффи, который благодаря случайно съеденному дьявольскому фрукту обрёл резиновое тело и вместе с командой отправился на поиски легендарного сокровища Ван-Пис. Один из самых продолжительных и коммерчески успешных аниме-сериалов в истории.","fact":"Манга-первоисточник сериала официально признана самой продаваемой серией комиксов одного автора в истории.","wiki_en":"One Piece"},{"name":"Атака титанов","emoji":"🗡️","meta":["аниме","2013–2023","Япония"],"description":"Человечество укрылось за гигантскими стенами от человекоподобных великанов-титанов, пожирающих людей, пока однажды стена не рушится под ударом Титана-Колосса. Сериал постепенно раскрывает сложную политическую и историческую подоплёку конфликта людей и титанов.","fact":"По словам автора манги Хадзимэ Исаямы, замысел родился отчасти из его опыта работы в интернет-кафе и общения с непредсказуемыми посетителями.","wiki_en":"Attack on Titan"},{"name":"Тетрадь смерти","emoji":"📓","meta":["аниме","2006–2007","Япония"],"description":"Старшеклассник Лайт Ягами находит тетрадь смерти, способную убить любого, чьё имя в неё вписано, и решает с её помощью очистить мир от преступников, превращаясь в загадочного вершителя правосудия по прозвищу Кира. Против него начинает расследование гениальный детектив L.","fact":"Правила использования тетради смерти настолько детально продуманы, что фанаты годами разбирают их логические лазейки и противоречия.","wiki_en":"Death Note"},{"name":"Покемон","emoji":"⚡","meta":["аниме","с 1997","Япония"],"description":"Аниме о юном тренере Эше Кетчуме и его электрическом покемоне Пикачу, которые путешествуют по разным регионам, ловят и тренируют других покемонов и участвуют в турнирах, чтобы стать чемпионами. Основано на культовой серии видеоигр и породило одну из крупнейших медиафраншиз в мире.","fact":"Один из эпизодов 1997 года вызвал у японских зрителей приступы из-за часто мигающих кадров и после этого никогда больше не выходил в эфир.","wiki_en":"Pokémon (TV series)"},{"name":"Сейлор Мун","emoji":"🌙","meta":["аниме","1992–1997","Япония"],"description":"Обычная японская школьница Усаги Цукино превращается в воительницу в матроске Сейлор Мун и вместе с другими девушками-воительницами защищает Землю от тёмных сил. Один из первых по-настоящему массово популярных аниме о волшебницах-воительницах за пределами Японии.","fact":"Сериал сыграл ключевую роль в популяризации жанра махо-сёдзё и аниме в целом среди западной аудитории в девяностые годы.","wiki_en":"Sailor Moon (TV series)"},{"name":"Мистер Бин","emoji":"🧸","meta":["комедия","1990–1995","Великобритания"],"description":"Комедийный сериал почти без диалогов о нелепом и эксцентричном англичанине мистере Бине, чьи простейшие бытовые ситуации неизменно превращаются в цепочку абсурдных недоразумений. Физический, визуальный юмор сделал шоу понятным зрителям независимо от языка.","fact":"Из-за минимального количества реплик сериал легко экспортировался по всему миру почти без адаптации и озвучки.","wiki_en":"Mr. Bean"},{"name":"Доктор Кто","emoji":"📞","meta":["фантастика","с 1963","Великобритания"],"description":"Многолетний британский сериал о путешествующем во времени и пространстве инопланетянине Докторе, который летает на машине времени в виде синей полицейской будки и периодически «перерождается» в новое тело. Один из самых долгоживущих научно-фантастических сериалов на телевидении.","fact":"Способность Доктора «перерождаться» изначально придумали как сюжетный ход, чтобы заменить исполнителя главной роли без остановки сериала.","wiki_en":"Doctor Who"},{"name":"Зачарованные","emoji":"🔮","meta":["фэнтези, драма","1998–2006","США"],"description":"Три сестры Холливелл узнают, что они потомки могущественного рода ведьм, и должны использовать унаследованную магию, чтобы защищать невинных от демонов и тёмных сил. Сериал сочетает семейную драму с еженедельными магическими сражениями.","fact":"Сериал стал одним из самых долгоживущих телешоу с главными героинями-женщинами в жанре фэнтези на американском телевидении.","wiki_en":"Charmed"},{"name":"Спасатели Малибу","emoji":"🏖️","meta":["драма, экшн","1989–2001","США"],"description":"Сериал о буднях спасателей на пляжах Малибу, которые не только вытаскивают из воды тонущих отдыхающих, но и распутывают личные драмы и криминальные истории. В девяностые считался одним из самых просматриваемых телесериалов в мире.","fact":"На пике популярности сериал, по разным оценкам, еженедельно смотрело более миллиарда зрителей по всему миру.","wiki_en":"Baywatch"},{"name":"Альф","emoji":"👽","meta":["комедия","1986–1990","США"],"description":"После крушения инопланетного корабля на Земле пушистое существо по имени Альф поселяется в доме обычной американской семьи, скрываясь от властей и то и дело устраивая бытовой хаос. Персонаж Альфа — кукла-аниматроник, управляемая кукловодом из-под пола.","fact":"Из-за кукольной механики Альфа редко показывали в полный рост, а декорации приподняли над полом, чтобы под ними работали кукловоды.","wiki_en":"ALF (TV series)"},{"name":"Санта-Барбара","emoji":"🌴","meta":["мыльная опера","1984–1993","США"],"description":"Многолетняя американская мыльная опера о жизни, любви и интригах нескольких богатых семей калифорнийского города Санта-Барбара. В постсоветских странах сериал стал одним из первых массово популярных иностранных телесериалов девяностых.","fact":"Сериал выходил почти десять лет и насчитывает больше двух тысяч эпизодов — по одному почти на каждый рабочий день.","wiki_en":"Santa Barbara (TV series)"},{"name":"Менталист","emoji":"🎯","meta":["детектив, драма","2008–2015","США"],"description":"Бывший фальшивый экстрасенс Патрик Джейн помогает калифорнийскому бюро расследований раскрывать преступления, используя не сверхспособности, а острую наблюдательность и знание психологии. Параллельно герой ведёт личную охоту на серийного убийцу, погубившего его семью.","fact":"Прототипом главного героя во многом послужили реальные менталисты и «холодные чтецы», которые создают иллюзию чтения мыслей без всякой мистики.","wiki_en":"The Mentalist"},{"name":"Форс-мажоры","emoji":"👔","meta":["драма","2011–2019","США"],"description":"Талантливый молодой человек без диплома юриста устраивается на работу в престижную нью-йоркскую юридическую фирму благодаря невероятной памяти и хитрости, скрывая от коллег и клиентов обман. Сериал сочетает юридическую драму с историей дружбы и наставничества.","fact":"Оригинальное английское название Suits обыгрывает и деловые костюмы юристов, и судебные иски, которые ведут герои.","wiki_en":"Suits (American TV series)"},{"name":"Люцифер","emoji":"😈","meta":["фэнтези, детектив","2016–2021","США"],"description":"Дьявол устаёт от вечного правления Адом и переезжает в Лос-Анджелес, где открывает ночной клуб и по совместительству помогает полиции раскрывать убийства благодаря способности заставлять людей признаваться в своих желаниях. Сериал основан на персонаже комиксов издательства Vertigo.","fact":"Персонаж Люцифера впервые появился ещё в комиксах «Песочный человек» Нила Геймана до того, как получил собственную серию комиксов и сериал.","wiki_en":"Lucifer (TV series)"},{"name":"Сверхъестественное","emoji":"🔥","meta":["фэнтези, ужасы","2005–2020","США"],"description":"Братья Сэм и Дин Винчестеры колесят по Америке на старом «Шевроле Импала», охотясь на демонов, призраков и прочую нечисть, попутно оказываясь в центре противостояния Рая и Ада. Один из самых долгоживущих сериалов в жанре фэнтези-ужасов на американском телевидении.","fact":"Чёрный «Шевроле Импала» 1967 года, на котором ездят герои, стал таким же узнаваемым символом сериала, как и сами братья.","wiki_en":"Supernatural (American TV series)","img":"Supernatural_Season_1.jpg"},{"name":"Дневники вампира","emoji":"🧛","meta":["фэнтези, драма","2009–2017","США"],"description":"Старшеклассница Елена Гилберт влюбляется в благородного вампира Стефана Сальваторе, но вскоре в её жизни появляется его непредсказуемый брат Дэймон, и оба брата оказываются втянуты в вечное соперничество за её сердце. Действие происходит в маленьком городке Мистик-Фоллс, полном сверхъестественных существ.","fact":"Съёмки сериала проходили в реальном городке Ковингтон в штате Джорджия, который стал популярным местом паломничества фанатов.","wiki_en":"The Vampire Diaries"},{"name":"Мир Дикого Запада","emoji":"🤖","meta":["фантастика, драма","2016–2022","США"],"description":"Огромный тематический парк развлечений населён человекоподобными андроидами, которые изо дня в день разыгрывают сюжеты вестерна для богатых посетителей, пока в их программах не начинают проступать признаки настоящего сознания. Сериал поднимает вопросы о природе сознания и свободы воли.","fact":"Сериал основан на одноимённом фантастическом фильме 1973 года, который был одним из первых голливудских фильмов с компьютерной анимацией.","wiki_en":"Westworld (TV series)"},{"name":"Фарго","emoji":"❄️","meta":["чёрная комедия, криминал","с 2014","США"],"description":"Антологический сериал по мотивам одноимённого фильма братьев Коэн, каждый сезон которого рассказывает отдельную историю о нелепых и кровавых преступлениях среди заснеженных пейзажей американского Среднего Запада. Сериал сохраняет фирменную коэновскую смесь чёрного юмора и внезапного насилия.","fact":"Несмотря на антологический формат с новыми героями каждый сезон, некоторые сюжетные детали едва заметно связывают все сезоны между собой.","wiki_en":"Fargo (TV series)"},{"name":"Мистер Робот","emoji":"💻","meta":["драма, триллер","2015–2019","США"],"description":"Талантливый, но психически нестабильный программист-хакер по ночам вступает в подпольную группу анархистов, которая планирует уничтожить долговые записи крупнейшей корпорации мира. Сериал известен точным изображением реального хакерства и нестандартной операторской работой.","fact":"Создатель сериала Сэм Эсмейл увлекался программированием с юности и держал на площадке консультантов по кибербезопасности ради достоверности сцен взлома.","wiki_en":"Mr. Robot"},{"name":"Бруклин 9-9","emoji":"👮","meta":["ситком","2013–2021","США"],"description":"Комедийный сериал о буднях эксцентричных детективов нью-йоркского полицейского участка Бруклин 9-9 во главе со строгим, но справедливым капитаном Рэймондом Холтом. Сочетает полицейские расследования с непрекращающимися розыгрышами и дружескими подколками между напарниками.","fact":"Капитан Холт в сериале — один из первых открыто гомосексуальных чернокожих героев в главной роли комедийного сериала на американском телевидении.","wiki_en":"Brooklyn Nine-Nine"},{"name":"Сайнфелд","emoji":"🥨","meta":["ситком","1989–1998","США"],"description":"Ситком о нью-йоркском комике Джерри Сайнфелде и трёх его чудаковатых друзьях, чьи серии часто строятся вокруг совершенно бытовых мелочей и абсурдных мелких конфликтов. Сам сериал шутливо называли «шоу ни о чём» за отсутствие сквозных сюжетных линий.","fact":"Финал 1998 года собрал у экранов десятки миллионов американцев и стал одним из самых массово просмотренных финалов в истории телевидения.","wiki_en":"Seinfeld"},{"name":"Бригада","emoji":"🔫","meta":["драма, криминал","2002","Россия"],"description":"Сериал о четырёх друзьях детства, которые в постсоветской Москве девяностых постепенно превращаются из обычных парней в лидеров крупной криминальной группировки. Прослеживает восхождение и неизбежное падение банды на фоне бурной эпохи девяностых.","fact":"Актёр Сергей Безруков, сыгравший главаря банды Сашу Белого, после выхода сериала долгие годы ассоциировался у зрителей именно с этой ролью.","wiki_en":"Brigada"},{"name":"Семнадцать мгновений весны","emoji":"🕵️","meta":["драма, шпионский","1973","СССР"],"description":"Советский разведчик Максим Исаев, работающий под именем штандартенфюрера Штирлица в структурах нацистской Германии, пытается предотвратить сепаратные переговоры немцев с западными союзниками в последние месяцы войны. Один из самых культовых советских телесериалов.","fact":"Фразы и сцены из сериала настолько прочно вошли в культуру, что породили целый жанр анекдотов про Штирлица.","wiki_en":"Seventeen Moments of Spring"},{"name":"Место встречи изменить нельзя","emoji":"🚔","meta":["детектив, драма","1979","СССР"],"description":"Экранизация романа братьев Вайнеров о работе московского уголовного розыска в первые послевоенные годы, где опытный сыщик Глеб Жеглов и молодой Владимир Шарапов расходятся во взглядах на методы борьбы с преступностью. Сериал считается одним из лучших советских детективов.","fact":"Роль Глеба Жеглова, сыгранная Владимиром Высоцким, стала одной из последних крупных работ актёра перед смертью.","wiki_en":"The Meeting Place Cannot Be Changed"},{"name":"Ликвидация","emoji":"🕶️","meta":["детектив, драма","2007","Россия, Украина"],"description":"Действие детективного сериала разворачивается в послевоенной Одессе 1946 года, где сотрудники уголовного розыска пытаются справиться с разгулом бандитизма во главе с загадочным преступным авторитетом по кличке Академик. Сериал воссоздаёт колоритную атмосферу и говор послевоенной Одессы.","fact":"Одесский диалект и характерные выражения героев сериала быстро разошлись на цитаты далеко за пределами города.","wiki_en":"Liquidation (miniseries)","wiki_ru":"Ликвидация (телесериал)"},{"name":"Улицы разбитых фонарей","emoji":"🌃","meta":["детектив","с 1997","Россия"],"description":"Один из первых и самых долгоживущих российских детективных сериалов о буднях оперативников петербургского уголовного розыска, которые в каждой серии расследуют новое преступление. Сериал породил целую волну похожих отечественных детективных франшиз.","fact":"Основой сериала стали книги Андрея Кивинова, который сам служил в петербургском уголовном розыске.","wiki_en":"Streets of Broken Lights"},{"name":"Интерны","emoji":"🩺","meta":["ситком","2010–2016","Россия"],"description":"Комедийный сериал о буднях молодых врачей-интернов московской больницы под руководством едкого и требовательного доктора Быкова. Формат во многом ориентирован на популярные американские медицинские ситкомы, адаптированные под российские реалии.","fact":"Главную роль едкого доктора Быкова сыграл Иван Охлобыстин, до сериала известный скорее как актёр авторского кино и сценарист.","wiki_en":"Interns (TV series)","wiki_ru":"Интерны"},{"name":"Кухня","emoji":"🍳","meta":["ситком","2012–2016","Россия"],"description":"Ситком о поварах и персонале дорогого ресторана, где талантливый, но неопытный молодой повар пытается пробиться под руководством вспыльчивого и требовательного шеф-повара. Сериал породил несколько полнометражных продолжений и спин-оффов.","fact":"Вспыльчивого шеф-повара Виктора Баринова сыграл Дмитрий Назаров, и именно этот образ стал самым узнаваемым в сериале.","wiki_en":"Kitchen (TV series)","wiki_ru":"Кухня (телесериал)"},{"name":"Универ","emoji":"🎓","meta":["ситком","2007–2011","Россия"],"description":"Молодёжный ситком о жизни студентов, живущих в общежитии одного из московских университетов, снятый в формате многокамерного ситкома со зрительским смехом за кадром. Сериал стал одним из самых заметных проектов российского молодёжного телевидения двухтысячных.","fact":"У сериала появилось продолжение — «Универ. Новая общага», где действие в той же общаге продолжилось уже с новыми героями.","wiki_en":"Univer (Russian TV series)","wiki_ru":"Универ (телесериал)"},{"name":"Физрук","emoji":"🏋️","meta":["ситком","2014–2018","Россия"],"description":"Бывший криминальный авторитет по прозвищу Фома после выхода из тюрьмы устраивается на работу учителем физкультуры в обычную школу, принося в размеренную школьную жизнь свои криминальные повадки и специфическое чувство юмора. Главную роль сыграл актёр Дмитрий Нагиев.","fact":"В школу Фома идёт вовсе не по призванию — ему нужно подобраться поближе к дочери своего бывшего шефа.","wiki_en":"Fizruk"},{"name":"Сваты","emoji":"🍷","meta":["комедия","2008–2019","Украина, Россия"],"description":"Комедийный сериал о двух семьях свойственников с разным достатком и взглядами на жизнь, чьи дети поженились, а сами родители вынуждены то и дело общаться и мириться с характерами друг друга. Действие в основном происходит в деревенском доме одной из семей.","fact":"Сериал снимался на Украине, а его актёрский состав объединил известных актёров сразу из нескольких постсоветских стран.","wiki_en":"Svaty","wiki_ru":"Сваты"},{"name":"Папины дочки","emoji":"👧","meta":["ситком","2007–2013","Россия"],"description":"Ситком о папе-психологе, который после ухода жены в одиночку воспитывает пятерых очень разных по характеру дочерей и с трудом справляется с их выходками. Снят в формате многокамерного ситкома со зрительским смехом за кадром.","fact":"Спустя годы после финала сериал получил продолжение, где выросшие героини вернулись уже вместе с новым поколением детей.","wiki_en":"Daddy's Daughters"},{"name":"Моя прекрасная няня","emoji":"🧹","meta":["ситком","2004–2009","Россия"],"description":"Ситком о простодушной, но обаятельной провинциальной девушке, которая неожиданно становится няней в доме богатого столичного продюсера и постепенно покоряет сердца всей его семьи. Сериал — российская адаптация американского ситкома «Няня».","fact":"Героиня приехала в Москву из Мариуполя, и её яркий говор с характерными интонациями стал визитной карточкой сериала.","wiki_en":"My Fair Nanny (TV series)","wiki_ru":"Моя прекрасная няня"},{"name":"Не родись красивой","emoji":"👓","meta":["мелодрама","2005–2006","Россия"],"description":"Мелодрама о скромной и не слишком привлекательной по меркам глянца девушке, которая устраивается на работу в модный дом и вопреки насмешкам коллег постепенно добивается успеха и любви. Сериал — российская адаптация популярного латиноамериканского телеформата об утёнке, покоряющем мир моды.","fact":"Оригинальный формат сериала, колумбийская теленовелла, был адаптирован на телевидении десятков стран мира, и российская версия стала одной из самых успешных.","wiki_en":"Not Born Beautiful","wiki_ru":"Не родись красивой"},{"name":"Слово пацана. Кровь на асфальте","emoji":"🥊","meta":["драма, криминал","2023","Россия"],"description":"Драма о подростковых уличных группировках в Казани конца восьмидесятых годов, где мальчишки из разных дворов живут по жёстким неписаным законам улицы. Сериал вызвал широкое общественное обсуждение подростковой преступности после выхода.","fact":"После премьеры сериала в нескольких российских регионах прошли специальные обсуждения и профилактические меры из-за опасений подражания героям среди подростков.","wiki_en":"The Boy's Word: Blood on the Asphalt"},{"name":"Эпидемия","emoji":"❄️","meta":["драма, триллер","2019–2022","Россия"],"description":"После вспышки смертельного вируса в России группа случайных попутчиков пытается на машине добраться сквозь опустевшую и погружённую в хаос страну до безопасного укрытия на удалённом озере. Сериал снят по мотивам романа Яны Вагнер «Вонгозеро».","fact":"Российская премьера прошла незадолго до начала пандемии COVID-19, а на Netflix сериал вышел под названием To the Lake.","wiki_en":"To the Lake"},{"name":"Мажор","emoji":"🚓","meta":["драма, криминал","2014–2019","Россия"],"description":"Избалованный сын высокопоставленного чиновника после серьёзного проступка отправляется отцом служить рядовым оперативником в московскую полицию, где ему приходится с нуля заслуживать уважение коллег. Сериал сочетает детективные сюжеты с историей взросления избалованного героя.","fact":"После телевизионных сезонов историю героя продолжили в полнометражном фильме, вышедшем уже в кинопрокат.","wiki_en":"Silver Spoon (Russian TV series)","wiki_ru":"Мажор (телесериал)"},{"name":"Метод","emoji":"🔦","meta":["детектив, триллер","2015–2018","Россия"],"description":"Эксцентричный следователь с неординарными, почти пугающими методами расследования берёт в напарницы молодую сотрудницу полиции, чтобы вместе охотиться на маньяков и серийных убийц. Сериал известен мрачной атмосферой и нестандартной операторской работой.","fact":"Главную роль сыграл актёр Константин Хабенский, а сериал сравнивали по стилистике с зарубежными триллерами о серийных убийцах.","wiki_en":"The Method (TV series)"},{"name":"Полицейский с Рублёвки","emoji":"🚨","meta":["комедия","2016–2019","Россия"],"description":"Простоватый участковый переводится служить в элитный посёлок для сверхбогатых на Рублёвке, где ему приходится разбираться с капризами и странностями обеспеченных жителей, оставаясь в душе честным и бесхитростным человеком. Сериал сочетает полицейские сюжеты с комедией нравов.","fact":"У сериала вышло полнометражное продолжение «Полицейский с Рублёвки. Новогодний беспредел», ставшее хитом российского кинопроката.","wiki_en":"A Cop from Rublyovka","wiki_ru":"Полицейский с Рублёвки"},{"name":"Ну, погоди!","emoji":"🐺","meta":["мультфильм","с 1969","СССР"],"description":"Советский мультсериал о нескладном, но упрямом Волке, который на протяжении множества коротких серий безуспешно пытается поймать весёлого и находчивого Зайца. Почти лишённый диалогов сериал построен на выразительной пантомиме и музыкальных номерах.","fact":"Реплику «Ну, заяц, погоди!», произносимую Волком почти в каждой серии, зрители запомнили настолько, что она дала название всему мультсериалу.","wiki_en":"Well, Just You Wait!"},{"name":"Смешарики","emoji":"🐰","meta":["мультсериал","с 2004","Россия"],"description":"Российский мультсериал о круглых забавных существах-шариках, которые живут в вымышленном лесном мире и через простые бытовые истории знакомят маленьких зрителей с основами дружбы, науки и взаимопомощи. Сериал экспортировался и адаптировался для показа во многих странах мира.","fact":"За рубежом сериал выходил под другими названиями, включая версии GoGoRiki и KikoRiki для разных международных рынков.","wiki_en":"Smeshariki"},{"name":"Маша и Медведь","emoji":"🐻","meta":["мультсериал","с 2009","Россия"],"description":"Мультсериал о неугомонной маленькой девочке Маше, которая своими бесконечными шалостями постоянно испытывает терпение приютившего её доброго, но уставшего от её энергии медведя. Один из самых успешных российских анимационных проектов, завоевавших популярность далеко за пределами страны.","fact":"Эпизод «Маша плюс каша» набрал на YouTube миллиарды просмотров и стал одним из самых просматриваемых видео в истории сервиса.","wiki_en":"Masha and the Bear"},{"name":"Родина","emoji":"🎯","meta":["политический триллер","2011–2020","США"],"description":"Офицер ЦРУ Кэрри Мэтисон, страдающая биполярным расстройством, подозревает вернувшегося из плена морского пехотинца в связях с террористами. Сериал снят по мотивам израильского «Хатуфим» и держит зрителя в напряжении политической интригой и игрой Клэр Дэйнс.","fact":"Сериал основан на израильском проекте «Хатуфим», созданном Гидеоном Раффом.","wiki_en":"Homeland (TV series)"},{"name":"Обмани меня","emoji":"👁️","meta":["криминальная драма","2009–2011","США"],"description":"Психолог Кэл Лайтман и его коллеги раскрывают преступления, считывая микровыражения лиц и язык тела людей. Каждая серия сочетает детективный сюжет с почти документальными вставками о природе лжи и эмоций.","fact":"Прототипом главного героя стал реальный психолог Пол Экман, консультировавший создателей сериала.","wiki_en":"Lie to Me","wiki_ru":"Обмани меня (телесериал, 2009)"},{"name":"Мыслить как преступник","emoji":"🧠","meta":["криминальная драма","2005–2020","США"],"description":"Агенты отдела поведенческого анализа ФБР составляют психологические портреты серийных преступников, чтобы предсказать их следующий шаг. Сериал сделал профайлинг одной из самых узнаваемых тем детективного телевидения.","fact":"Название отдела в сериале — Behavioral Analysis Unit — списано с реального подразделения ФБР в Куантико.","wiki_en":"Criminal Minds","wiki_ru":"Мыслить как преступник"},{"name":"Готэм","emoji":"🦇","meta":["криминальная драма","2014–2019","США"],"description":"События разворачиваются в Готэм-сити за годы до того, как Брюс Уэйн стал Бэтменом, а молодой детектив Джеймс Гордон только начинает бороться с преступностью. По ходу сюжета зритель наблюдает превращение будущих злодеев комиксов DC в узнаваемых персонажей.","fact":"Создатели сериала обещали показать становление почти всех классических противников Бэтмена ещё до его появления.","wiki_en":"Gotham (TV series)","wiki_ru":"Готэм (телесериал)"},{"name":"Флэш","emoji":"⚡","meta":["супергероика","2014–2023","США"],"description":"Криминалист Барри Аллен получает сверхскорость после удара молнии и становится супергероем, защищающим Central City. Сериал — часть так называемой Стрелверс, киновселенной телеканала The CW, связанной со «Стрелой» и «Супергёрл».","fact":"Роль Барри Аллена исполнил Грант Гастин, впервые появившийся в этом образе ещё в эпизодах «Стрелы».","wiki_en":"The Flash (2014 TV series)","wiki_ru":"Флэш (телесериал, 2014)"},{"name":"Стрела","emoji":"🏹","meta":["супергероика","2012–2020","США"],"description":"Миллиардер Оливер Куин возвращается после пяти лет на необитаемом острове и начинает бороться с преступностью Стар-Сити под маской лучника-мстителя. Сериал положил начало целой сети связанных супергеройских шоу канала The CW.","fact":"Именно «Стрела» открыла так называемую Стрелверс — общую вселенную нескольких сериалов CW о супергероях.","wiki_en":"Arrow (TV series)"},{"name":"Супергёрл","emoji":"🦸‍♀️","meta":["супергероика","2015–2021","США"],"description":"Кара Дэнверс, кузина Супермена, годами скрывала свои способности, пока не решила открыто встать на защиту National City. Сериал сочетает супергеройский экшен с темами становления личности и веры в себя.","fact":"Кара Дэнверс появилась на Криптоне ещё до Супермена, но из-за задержки в пути прилетела на Землю позже него.","wiki_en":"Supergirl (TV series)"},{"name":"Видоизменённый углерод","emoji":"🧬","meta":["киберпанк","2018–2020","США"],"description":"В далёком будущем человеческое сознание можно переносить между телами-«оболочками», а бывший солдат-мятежник Такеси Ковач расследует убийство одного из самых богатых людей планеты. Сериал снят по роману Ричарда Моргана и славится мрачной киберпанк-эстетикой.","fact":"Оболочку главного героя в разных сезонах играли разные актёры — это часть сюжетной механики сериала.","wiki_en":"Altered Carbon (TV series)"},{"name":"Академия Амбрелла","emoji":"☂️","meta":["супергероика","2019–2024","США"],"description":"Семеро приёмных детей с необычными способностями, усыновлённых эксцентричным миллиардером, вынуждены снова собраться вместе, чтобы предотвратить конец света. Сериал снят по комиксам Джерарда Уэя, лидера группы My Chemical Romance.","fact":"Один из братьев, Номер Пять, застрял в будущем на десятки лет и вернулся обратно в теле подростка.","wiki_en":"The Umbrella Academy (TV series)"},{"name":"Ты","emoji":"📚","meta":["психологический триллер","2018–2025","США"],"description":"Обаятельный работник книжного магазина Джо Голдберг одержимо влюбляется в женщин и готов на любые манипуляции, чтобы оказаться рядом с объектом своей страсти. Сериал снят по роману Кэролайн Кепнес и построен на закадровом внутреннем монологе героя.","fact":"Сериал изначально выходил на канале Lifetime и стал хитом только после того, как права выкупил Netflix.","wiki_en":"You (TV series)","wiki_ru":"Ты (телесериал)"},{"name":"Половое воспитание","emoji":"🎓","meta":["подростковая драма","2019–2023","Великобритания"],"description":"Застенчивый школьник Отис, чья мать работает секс-терапевтом, неожиданно для себя открывает в школе неофициальную консультацию по вопросам отношений и сексуальности. Сериал сочетает откровенный юмор с тёплой историей взросления.","fact":"Съёмки сериала проходили в Уэльсе, хотя по сюжету действие происходит в вымышленном английском городке.","wiki_en":"Sex Education (TV series)"},{"name":"Убивая Еву","emoji":"🔪","meta":["криминальный триллер","2018–2022","Великобритания"],"description":"Скучающий офицер спецслужб Ив Полстри получает задание выследить неуловимую и эксцентричную наёмную убийцу Вилланель, и между двумя женщинами возникает опасное взаимное притяжение. Сериал снят по циклу повестей Люка Дженнингса.","fact":"У каждого сезона сериала была своя шоураннер-женщина: первый написала Фиби Уоллер-Бридж, следующие — другие авторы.","wiki_en":"Killing Eve"},{"name":"Настоящая кровь","emoji":"🩸","meta":["хоррор-драма","2008–2014","США"],"description":"После изобретения синтетической крови вампиры выходят из тени и пытаются встроиться в жизнь маленького городка в Луизиане, где официантка Суки Стэкхаус обладает собственным необычным даром. Сериал снят по циклу романов Шарлин Харрис.","fact":"Название сериала обыгрывает выражение true blood — «настоящая кровь» в противовес синтетической, которую пьют вампиры.","wiki_en":"True Blood","wiki_ru":"Настоящая кровь"},{"name":"Тюрьма Оз","emoji":"🔒","meta":["тюремная драма","1997–2003","США"],"description":"Жизнь заключённых экспериментального блока строгого режима «Эмеральд-Сити» показана без прикрас — с насилием, бандами и борьбой за выживание. Это один из первых оригинальных драматических сериалов HBO, открывший каналу дорогу к «взрослому» телевидению.","fact":"Сериал считается предшественником таких проектов HBO, как «Клан Сопрано» и «Прослушка».","wiki_en":"Oz (TV series)"},{"name":"24 часа","emoji":"⏱️","meta":["шпионский триллер","2001–2010","США"],"description":"Каждый сезон рассказывает о сутках из жизни агента контртеррористического подразделения Джека Бауэра — в реальном времени, серия за серией, час за часом. Формат «реального времени» с обратным отсчётом стал визитной карточкой сериала.","fact":"Часы на экране идут без остановки даже во время рекламных пауз — это часть фирменного стиля шоу.","wiki_en":"24 (TV series)"},{"name":"C.S.I.: Место преступления","emoji":"🔬","meta":["криминальная драма","2000–2015","США"],"description":"Команда криминалистов Лас-Вегаса раскрывает преступления с помощью судебной экспертизы — отпечатков, анализа крови и баллистики. Сериал сделал криминалистику мейнстримной темой и породил несколько спин-оффов по всему миру.","fact":"Популярность шоу породила так называемый «эффект CSI» — рост завышенных ожиданий присяжных от реальной судебной экспертизы.","wiki_en":"CSI: Crime Scene Investigation"},{"name":"C.S.I.: Майами","emoji":"🕶️","meta":["криминальная драма","2002–2012","США"],"description":"Спин-офф о команде криминалистов солнечного Майами во главе с лейтенантом Горацио Кейном, известным своими эффектными фразами перед заставкой. Сериал сохранил формат оригинала, добавив более яркую, кинематографичную картинку.","fact":"Фраза «Yeah» и характерная пауза перед сменой сцены Горацио Кейна стали интернет-мемом.","wiki_en":"CSI: Miami"},{"name":"Закон и порядок","emoji":"⚖️","meta":["криминальная драма","1990–2010","США"],"description":"Каждая серия делится на две части: сначала полицейские расследуют преступление, затем прокуроры доводят дело до суда. Формат «дело за серию» и узнаваемая отбивка-заставка сделали сериал одним из самых долгоживущих в истории американского телевидения.","fact":"Франшиза «Закон и порядок» породила несколько спин-оффов и была возобновлена в 2022 году после долгого перерыва.","wiki_en":"Law & Order","wiki_ru":"Закон и порядок"},{"name":"Закон и порядок: Специальный корпус","emoji":"🛡️","meta":["криминальная драма","с 1999","США"],"description":"Спин-офф «Закона и порядка» посвящён подразделению нью-йоркской полиции, расследующему преступления на сексуальной почве, во главе с детективом Оливией Бенсон. Это один из самых долгоживущих прайм-тайм сериалов США.","fact":"Мариска Харгитей играет Оливию Бенсон с самого первого сезона 1999 года — дольше, чем любой другой герой франшизы.","wiki_en":"Law & Order: Special Victims Unit","wiki_ru":"Закон и порядок: Специальный корпус"},{"name":"Кости","emoji":"🦴","meta":["криминальная драма","2005–2017","США"],"description":"Судебный антрополог Темперанс Бреннан вместе с агентом ФБР Сили Бутом раскрывает преступления по костным останкам жертв. Сериал снят по мотивам произведений писательницы и антрополога Кэти Райх, консультировавшей съёмочную группу.","fact":"Внутри сериала Бреннан сама пишет детективы, и её книжную героиню зовут Кэти Райх — в честь реального прототипа.","wiki_en":"Bones (TV series)"},{"name":"Касл","emoji":"🖋️","meta":["детектив","2009–2016","США"],"description":"Популярный автор детективов Ричард Касл добивается разрешения сопровождать нью-йоркского детектива Кейт Беккет в расследованиях, чтобы находить вдохновение для новых романов. Сериал держится на лёгкой химии между главными героями и остроумных диалогах.","fact":"Книги, которые «пишет» персонаж Касла, действительно издавались как настоящие бестселлеры под его именем.","wiki_en":"Castle (TV series)"},{"name":"Морская полиция: Спецотдел","emoji":"⚓","meta":["криминальная драма","с 2003","США"],"description":"Специальный отдел морской полиции расследует преступления, связанные с военными моряками и морской пехотой США. Сериал вырос из спин-оффа «Военно-юридической службы» и стал одним из самых долгоживущих драматических шоу американского телевидения.","fact":"NCIS расшифровывается как Naval Criminal Investigative Service — реально существующее агентство при ВМС США.","wiki_en":"NCIS (TV series)","wiki_ru":"Морская полиция: Спецотдел"},{"name":"Скорая помощь","emoji":"🏥","meta":["медицинская драма","1994–2009","США"],"description":"Жизнь врачей отделения неотложной помощи чикагской больницы показана в стремительном, почти документальном темпе смен и спасённых или потерянных жизней. Сериал придумал Майкл Крайтон и во многом задал стандарт всей медицинской драмы на десятилетия вперёд.","fact":"Одним из первых регулярных актёров сериала был Джордж Клуни, сыгравший педиатра Дага Росса.","wiki_en":"ER (TV series)"},{"name":"Западное крыло","emoji":"🏛️","meta":["политическая драма","1999–2006","США"],"description":"Сериал показывает будни вымышленной администрации президента США — от спичрайтеров до советника по национальной безопасности — глазами команды Белого дома. Создатель Аарон Соркин прославился фирменными длинными диалогами героев на ходу.","fact":"Приём съёмки на ходу с длинным диалогом получил у поклонников название walk and talk и стал визитной карточкой сериала.","wiki_en":"The West Wing","wiki_ru":"Западное крыло (телесериал)"},{"name":"Американская история ужасов","emoji":"👻","meta":["хоррор-антология","с 2011","США"],"description":"Каждый сезон рассказывает отдельную завершённую историю в жанре хоррора — от дома с привидениями до психиатрической лечебницы, — но актёрский состав переходит из сезона в сезон в новых ролях. Антологический формат позволил создателям Райану Мёрфи и Брэду Фэлчаку экспериментировать со стилями.","fact":"Многие актёры, включая Джессику Лэнг и Сару Полсон, играли совершенно разных персонажей в разных сезонах шоу.","wiki_en":"American Horror Story"},{"name":"Гримм","emoji":"📖","meta":["фэнтези-детектив","2011–2017","США"],"description":"Детектив полиции Портленда Ник Беркхардт узнаёт, что происходит из рода охотников на существ из сказок братьев Гримм, и должен совмещать обычную полицейскую работу с тайной охотой на монстров. Сериал соединяет процедурал «дело за серию» с мифологией скрытого мира.","fact":"Название сериала — прямая отсылка к братьям Гримм, чьи сказки переосмыслены как рассказы о реальных существах.","wiki_en":"Grimm (TV series)","wiki_ru":"Гримм (телесериал)"},{"name":"Тайны Смолвиля","emoji":"🌽","meta":["супергероика","2001–2011","США"],"description":"Сериал показывает взросление Кларка Кента в небольшом городке Смолвиль задолго до того, как он стал Суперменом, — с первой любовью, школьными проблемами и постепенным осознанием своих способностей. Долгие годы шоу держалось на негласном правиле никаких трико и полётов.","fact":"Создатели сериала долго избегали показывать героя в классическом костюме Супермена — это случилось лишь в самом финале.","wiki_en":"Smallville","wiki_ru":"Тайны Смолвиля"},{"name":"Звёздный путь","emoji":"🖖","meta":["научная фантастика","1966–1969","США"],"description":"Экипаж звездолёта «Энтерпрайз» во главе с капитаном Кирком исследует далёкий космос, встречая новые цивилизации и следуя принципу невмешательства. Сериал Джина Родденберри заложил основы одной из крупнейших научно-фантастических франшиз в истории.","fact":"Приветственный жест вулканца Спока «живи долго и процветай» придумал актёр Леонард Нимой на основе еврейского благословения коэнов.","wiki_en":"Star Trek: The Original Series","wiki_ru":"Звёздный путь: Оригинальный сериал"},{"name":"Звёздный крейсер Галактика","emoji":"🌌","meta":["научная фантастика","2004–2009","США"],"description":"После внезапного уничтожения человеческой цивилизации роботами-сайлонами немногочисленный флот людей во главе с военным крейсером «Галактика» ищет в космосе легендарную планету Земля. Мрачный перезапуск сериала 1978 года получил признание за глубину политических и религиозных тем.","fact":"Часть сайлонов в сериале неотличимы от людей внешне, что стало источником постоянного напряжения в сюжете.","wiki_en":"Battlestar Galactica (2004 TV series)"},{"name":"Ганнибал","emoji":"🍽️","meta":["психологический триллер","2013–2015","США"],"description":"Молодой профайлер ФБР Уилл Грэм сближается с блестящим психиатром Ганнибалом Лектером, не подозревая о его тёмной тайне. Сериал снят по мотивам персонажей Томаса Харриса и выделяется изощрённой, почти живописной визуальной эстетикой.","fact":"Несмотря на культовый статус, сериал был закрыт после трёх сезонов из-за невысоких рейтингов.","wiki_en":"Hannibal (TV series)","wiki_ru":"Ганнибал (телесериал)"},{"name":"Ривердэйл","emoji":"🍒","meta":["подростковая драма","2017–2023","США"],"description":"Персонажи классических комиксов об Арчи Эндрюсе оказываются в мрачной версии городка Ривердэйл, где за внешним уютом скрываются тайны и преступления. Сериал начинается как детектив об убийстве, но со временем всё больше уходит в жанровый эксперимент.","fact":"Сериал основан на комиксах Archie Comics, которые изначально были лёгкими подростковыми историями без всякого нуара.","wiki_en":"Riverdale (2017 TV series)"},{"name":"Волчонок","emoji":"🐺","meta":["подростковый хоррор","2011–2017","США"],"description":"Обычный школьник Скотт Маккол становится оборотнем после нападения загадочного зверя и должен научиться жить с новой природой, не теряя себя и друзей. Сериал вдохновлён одноимённым фильмом 1985 года, но развивает совершенно самостоятельный сюжет.","fact":"Несмотря на название, отсылающее к комедии 1985 года с Майклом Дж. Фоксом, тон сериала гораздо мрачнее оригинала.","wiki_en":"Teen Wolf (2011 TV series)","wiki_ru":"Волчонок (телесериал)"},{"name":"13 причин почему","emoji":"🎧","meta":["драма","2017–2020","США"],"description":"После трагической смерти одноклассницы школьник Клэй Дженсен получает набор аудиокассет, в которых она объясняет, какие события привели её к этому решению. Сериал снят по роману Джея Эшера и вызвал широкую общественную дискуссию о том, как телевидение говорит о подростковых травмах.","fact":"После первого сезона создатели по рекомендации психологов пересмотрели некоторые сцены для более поздних изданий.","wiki_en":"13 Reasons Why","wiki_ru":"13 причин почему"},{"name":"Отбросы","emoji":"🌩️","meta":["фантастическая комедия","2009–2013","Великобритания"],"description":"Группа молодых людей, отбывающих общественные работы, получает необычные способности после странной грозы и вынуждена учиться с ними уживаться, не переставая быть тем ещё сбродом. Сериал известен чёрным юмором и нарочито антигеройским тоном.","fact":"Актёр Роберт Шиэн, сыгравший одну из ключевых ролей, покинул проект после второго сезона.","wiki_en":"Misfits (TV series)"},{"name":"Скины","emoji":"🎉","meta":["подростковая драма","2007–2013","Великобритания"],"description":"Сериал показывает жизнь группы британских подростков — вечеринки, первую любовь, зависимости и семейные проблемы — без цензуры и назидательности. Каждые два сезона состав персонажей полностью обновляется, взрослея вместе с новым поколением актёров.","fact":"Почти весь актёрский состав каждого поколения набирался из непрофессиональных молодых актёров на открытых кастингах.","wiki_en":"Skins (British TV series)"},{"name":"Уилл и Грейс","emoji":"🏙️","meta":["ситком","1998–2006","США"],"description":"Гей-адвокат Уилл и его лучшая подруга Грейс делят квартиру в Нью-Йорке, а их эксцентричные друзья Джек и Карен добавляют шоу комедийной остроты. Сериал одним из первых на американском мейнстрим-телевидении сделал гея главным положительным героем ситкома.","fact":"После восьми сезонов сериал был возрождён в 2017 году и выходил ещё три дополнительных сезона.","wiki_en":"Will & Grace","wiki_ru":"Уилл и Грейс"},{"name":"Молодой Шелдон","emoji":"🧪","meta":["ситком","2017–2024","США"],"description":"Приквел «Теории большого взрыва» рассказывает о детстве гения Шелдона Купера в маленьком техасском городке, где его недюжинный интеллект не всегда находит понимание в семье и школе. Сериал снят в формате однокамерного ситкома с закадровым рассказчиком.","fact":"Роль рассказчика в сериале исполняет Джим Парсонс — тот самый актёр, что играл взрослого Шелдона в оригинальном шоу.","wiki_en":"Young Sheldon"},{"name":"Парки и зоны отдыха","emoji":"🌳","meta":["мокьюментари-ситком","2009–2015","США"],"description":"Неунывающая чиновница отдела парков небольшого городка Пауни Лесли Ноуп с почти наивным энтузиазмом пытается сделать жизнь горожан лучше, сталкиваясь с бюрократией и равнодушием коллег. Сериал снят в формате мокьюментари теми же продюсерами, что и «Офис».","fact":"Изначально сериал задумывался как прямой спин-офф «Офиса», но со временем превратился в самостоятельный проект.","wiki_en":"Parks and Recreation","wiki_ru":"Парки и зоны отдыха"},{"name":"30 Rock","emoji":"📺","meta":["ситком","2006–2013","США"],"description":"Сценаристка и шоураннер вымышленного скетч-шоу Лиз Лемон балансирует между капризными звёздами, эксцентричным начальником и хаосом внутри телекомпании NBC. Сериал Тины Фей построен на её собственном опыте работы над «Субботним вечером в прямом эфире».","fact":"Персонажа эксцентричного руководителя телесети сыграл Алек Болдуин, получивший за эту роль несколько премий «Эмми».","wiki_en":"30 Rock","wiki_ru":"Студия 30"},{"name":"Все ненавидят Криса","emoji":"🎒","meta":["ситком","2005–2009","США"],"description":"Сериал в полуавтобиографичной форме рассказывает о детстве и подростковых годах комика Криса Рока в бедном районе Бруклина 1980-х. Закадровый голос взрослого Криса, роль которого озвучивает сам Рок, комментирует происходящее с ироничной дистанцией.","fact":"По сюжету Криса возят учиться в школу на другом конце города, где он оказывается единственным чернокожим учеником.","wiki_en":"Everybody Hates Chris"},{"name":"Женаты... с детьми","emoji":"🛋️","meta":["ситком","1987–1997","США"],"description":"Незадачливый продавец обуви Эл Бланди, его ленивая семья и вечно ироничный тон сериала стали противоядием от слащавых семейных ситкомов восьмидесятых. Шоу одним из первых показало откровенно дисфункциональную, но по-своему любящую семью.","fact":"Сериал стал одним из первых шоу молодой телесети Fox и одним из главных хитов её раннего эфира.","wiki_en":"Married... with Children"},{"name":"Царь горы","emoji":"🍖","meta":["анимационный ситком","1997–2010","США"],"description":"Консервативный техасец Хэнк Хилл продаёт пропан и пропановые аксессуары, воспитывает необычного сына и пытается сохранить привычный уклад жизни в меняющемся мире. Сериал Майка Джаджа известен спокойным, почти реалистичным юмором в противовес абсурдной анимационной комедии.","fact":"Создатель сериала Майк Джадж сам озвучивает нескольких героев — и самого Хэнка Хилла, и его неразборчиво тараторящего соседа Бумхауэра.","wiki_en":"King of the Hill","wiki_ru":"Царь горы (мультсериал)"},{"name":"Американский папаша","emoji":"🦅","meta":["анимационный ситком","с 2005","США"],"description":"Агент ЦРУ Стэн Смит пытается сохранить идеальную с виду семью, попутно сражаясь с террористами и инопланетянами, а его домашний питомец — говорящий инопланетянин Роджер — вечно устраивает хаос. Сериал создан Сетом Макфарлейном как более сюрреалистичный аналог «Гриффинов».","fact":"Персонаж Роджер-инопланетянин может принимать бесконечное число обличий и профессий ради очередной сюжетной авантюры.","wiki_en":"American Dad!"},{"name":"Бивис и Батт-Хед","emoji":"🤘","meta":["анимационная комедия","1993–1997","США"],"description":"Два бестолковых подростка-металлиста комментируют музыкальные клипы и попадают в нелепые ситуации, воплощая карикатуру на подростковую лень и невежество. Сериал Майка Джаджа стал одним из символов эфира MTV девяностых.","fact":"Из-за нескольких случаев подражания опасным трюкам героев сериал подвергался критике и цензуре в США.","wiki_en":"Beavis and Butt-Head","wiki_ru":"Бивис и Баттхед"},{"name":"Дарья","emoji":"📓","meta":["анимационная комедия","1997–2002","США"],"description":"Саркастичная и равнодушная к школьным условностям школьница Дарья Морженду смотрит на глупости окружающих с ироничной дистанцией. Спин-офф «Бивиса и Батт-Хеда» получился гораздо более разговорным и наблюдательным, чем родительский сериал.","fact":"Впервые Дарья появилась именно в «Бивисе и Батт-Хеде» как второстепенная героиня, прежде чем получить собственное шоу.","wiki_en":"Daria (TV series)"},{"name":"Время приключений","emoji":"🍦","meta":["анимационное фэнтези","2010–2018","США"],"description":"Мальчик Финн и его лучший друг — волшебный пёс с растягивающимся телом Джейк — путешествуют по постапокалиптической стране Ооо, полной причудливых существ и королевств. Под внешне детской анимацией сериал скрывает неожиданно глубокие темы взросления и потери.","fact":"Мир сериала, страна Ооо, оказывается Землёй далёкого будущего после неназванной глобальной катастрофы.","wiki_en":"Adventure Time"},{"name":"Гравити Фолз","emoji":"🌲","meta":["анимационная мистика","2012–2016","США"],"description":"Брат и сестра-близнецы Диппер и Мэйбл проводят лето у эксцентричного двоюродного дедушки в городке Гравити-Фолз, полном загадочных существ и тайн. Сериал Алекса Хирша выстроен как одна большая головоломка с зашифрованными посланиями в титрах каждой серии.","fact":"Создатель сериала Алекс Хирш сам озвучивает и дядю Стэна, и главного злодея Билла Шифра.","wiki_en":"Gravity Falls"},{"name":"Барбоскины","emoji":"🐶","meta":["мультсериал","Россия"],"description":"Многодетная семья собако-подобных существ Барбоскиных решает повседневные бытовые и житейские вопросы, а каждая серия учит зрителя простым нравственным урокам. Это один из самых популярных отечественных мультсериалов последнего десятилетия.","fact":"У каждого из детей Барбоскиных есть чётко закреплённая черта характера — от находчивости до занудства.","wiki_en":"Barboskins","wiki_ru":"Барбоскины"},{"name":"Фиксики","emoji":"🔧","meta":["мультсериал","с 2010","Россия"],"description":"Крошечные человечки-фиксики живут внутри бытовой техники и чинят её изнутри, попутно на доступном языке объясняя детям, как устроены привычные вещи. Сериал сочетает познавательные элементы с тёплым юмором и узнаваемой музыкальной заставкой.","fact":"Идея сериала выросла из детской книги Эдуарда Успенского «Гарантийные человечки».","wiki_en":"The Fixies","wiki_ru":"Фиксики"},{"name":"Три кота","emoji":"🐱","meta":["мультсериал","с 2015","Россия"],"description":"Три котёнка-подростка — Коржик, Карамелька и Компот — исследуют мир вокруг себя, попадая в забавные и поучительные истории вместе с родителями-котами. Один из самых узнаваемых российских мультипликационных брендов для дошкольников.","fact":"Имена трёх котят — Коржик, Карамелька и Компот — сами по себе отсылают к домашней еде и сладостям.","wiki_en":"Kid-E-Cats","wiki_ru":"Три кота"},{"name":"Лунтик","emoji":"🌙","meta":["мультсериал","2006–2019","Россия"],"description":"Загадочное существо, родившееся из капли лунного молока и упавшее на Землю, знакомится с миром природы и учится дружбе, добру и взаимопомощи вместе с насекомыми-соседями. Сериал стал одним из самых узнаваемых и долгоживущих отечественных мультпроектов для дошкольников.","fact":"Имя героя происходит от слова «Луна» — по сюжету он появился на свет именно там, а затем упал на Землю.","wiki_en":"Luntik and His Friends","wiki_ru":"Лунтик и его друзья"},{"name":"Черепашки-ниндзя","emoji":"🐢","meta":["анимационный боевик","1987–1996","США"],"description":"Четыре мутировавшие черепахи-ниндзя — Леонардо, Донателло, Рафаэль и Микеланджело — вместе со своим наставником-крысой сражаются с преступностью Нью-Йорка под улицами города. Оригинальный мультсериал 1987 года превратил независимый комикс в один из главных поп-культурных феноменов эпохи.","fact":"Каждая из четырёх черепах носит повязку своего цвета и названа в честь художника эпохи Возрождения.","wiki_en":"Teenage Mutant Ninja Turtles (1987 TV series)"},{"name":"Утиные истории","emoji":"🦆","meta":["анимационное приключение","1987–1990","США"],"description":"Скупой миллиардер-утка Скрудж Макдак вместе с тремя внучатыми племянниками отправляется в опасные экспедиции за сокровищами по всему миру. Классический мультсериал студии Disney во многом определил облик приключенческой анимации конца восьмидесятых.","fact":"Персонаж Скруджа Макдака впервые появился ещё в комиксах художника Карла Баркса в 1947 году, задолго до сериала.","wiki_en":"DuckTales (1987 TV series)"},{"name":"Чип и Дейл спешат на помощь","emoji":"🐿️","meta":["анимационное приключение","1989–1990","США"],"description":"Бурундуки-детективы Чип и Дейл вместе со своей командой — мышкой-изобретательницей Гаечкой, силачом Рокфором и мухой Вжиком — расследуют дела, слишком мелкие для крупных сыщиков. Сериал стал одним из самых популярных проектов студии Disney конца восьмидесятых.","fact":"Название детективного агентства героев — «Спасатели» — обыгрывает контраст между крошечными сыщиками и большими проблемами.","wiki_en":"Chip 'n Dale: Rescue Rangers (TV series)","wiki_ru":"Чип и Дейл спешат на помощь"},{"name":"Чёрный плащ","emoji":"🦆","meta":["анимационный супергеройский сериал","1991–1992","США"],"description":"Загадочный супергерой-утка по прозвищу Чёрный Плащ защищает город Сент-Кэнард от банды нелепых, но опасных злодеев, попутно воспитывая приёмную дочь. Сериал пародирует классические образы супергероев вроде Бэтмена, сохраняя фирменный юмор студии Disney.","fact":"В русском дубляже фирменная фраза героя — «Я — ужас, летящий на крыльях ночи» — давно стала мемом.","wiki_en":"Darkwing Duck"},{"name":"Том и Джерри","emoji":"🐭","meta":["анимационная комедия","1940–1958","США"],"description":"Кот Том бесконечно и безуспешно пытается поймать хитрого мышонка Джерри в серии коротких немых или почти немых гэговых мультфильмов. Один из самых узнаваемых и долгоживущих мультипликационных дуэтов в истории кино удостоен нескольких премий «Оскар».","fact":"Несколько короткометражек цикла получили премию «Оскар» за лучший анимационный короткометражный фильм.","wiki_en":"Tom and Jerry","wiki_ru":"Том и Джерри"},{"name":"Луни Тюнз","emoji":"🐰","meta":["анимационная комедия","1930–1969","США"],"description":"Антология коротких мультфильмов студии Warner Bros. подарила миру Багза Банни, Даффи Дака, Порки Пига и десятки других персонажей с их фирменными комедийными выходками. Серия во многом определила язык американской анимационной комедии XX века.","fact":"Фраза Багза Банни «What's up, doc?» вошла в число самых узнаваемых реплик в истории американской анимации.","wiki_en":"Looney Tunes"},{"name":"Флинтстоуны","emoji":"🦕","meta":["анимационный ситком","1960–1966","США"],"description":"Семья Флинтстоунов живёт в каменном веке, но их быт пародирует типичный американский пригородный образ жизни середины XX века — с автомобилями на ножном ходу и бытовой техникой из динозавров. Это первый мультсериал, вышедший в прайм-тайм на американском телевидении.","fact":"Боевой клич Фреда Флинтстоуна «Ябба-дабба-ду!» стал одной из самых известных фраз в истории мультипликации.","wiki_en":"The Flintstones"},{"name":"Джетсоны","emoji":"🚀","meta":["анимационный ситком","1962–1963","США"],"description":"Семья Джетсонов живёт в футуристическом городе будущего с летающими машинами, роботами-помощниками и движущимися тротуарами. Сериал студии Hanna-Barbera задумывался как зеркальное отражение «Флинтстоунов» — только вместо каменного века здесь мир далёкого будущего.","fact":"Несмотря на всего один оригинальный сезон, «Джетсоны» остаются одним из самых узнаваемых образов будущего в поп-культуре XX века.","wiki_en":"The Jetsons"},{"name":"Скуби-Ду","emoji":"🐕","meta":["анимационный детектив","1969–1970","США"],"description":"Трусливый пёс Скуби-Ду и четверо его друзей-подростков разъезжают на фургоне «Мистери Машина» и разоблачают мнимых призраков и монстров, за которыми обычно скрываются самые обычные мошенники. Формат «дело за серию» и коронная фраза про несносных детишек стали классикой жанра.","fact":"Почти в каждой серии оригинального сериала таинственное чудовище оказывалось обычным человеком в маскарадном костюме.","wiki_en":"Scooby-Doo, Where Are You!"},{"name":"Клуб Винкс: Школа волшебниц","emoji":"🧚‍♀️","meta":["анимационное фэнтези","2004–2019","Италия"],"description":"Шестеро девушек-фей учатся управлять магией в Алфее — школе волшебства — и защищают Магическое измерение от тёмных сил. Итальянский мультсериал стал одним из самых узнаваемых европейских анимационных проектов, ориентированных на девочек.","fact":"Создатель сериала Иджинио Страффи вдохновлялся японским жанром махо-сёдзё — историями о девочках-волшебницах.","wiki_en":"Winx Club"},{"name":"Самурай Джек","emoji":"⏳","meta":["анимационный экшен","2001–2017","США"],"description":"Японский самурай, заброшенный злым демоном Аку в далёкое антиутопичное будущее, ищет способ вернуться в своё время и остановить зло в его истоке. Сериал Генди Тартаковски выделяется минималистичным визуальным стилем и почти немым повествованием.","fact":"После долгого перерыва сериал получил завершающий пятый сезон уже в 2017 году, спустя более десяти лет после четвёртого.","wiki_en":"Samurai Jack","wiki_ru":"Самурай Джек"},{"name":"Драконий жемчуг Зет","emoji":"🐉","meta":["сёнэн-аниме","1989–1996","Япония"],"description":"Воин-сайян Сон Гоку и его друзья защищают Землю от всё более могущественных противников, попутно собирая волшебные Драконьи жемчужины, исполняющие любое желание. Сериал стал одной из самых влиятельных аниме-франшиз, задавших моду на длинные бои и постепенное усиление героев.","fact":"Сериал является прямым продолжением более раннего аниме «Драконий жемчуг» по манге Акиры Ториямы.","wiki_en":"Dragon Ball Z"},{"name":"Стальной алхимик","emoji":"⚗️","meta":["сёнэн-аниме","2009–2010","Япония"],"description":"Братья Эдвард и Альфонс Элрик, лишившиеся частей тела при попытке воскресить мать запретной алхимией, ищут философский камень, способный вернуть им утраченное. Версия «Братство» ближе к оригинальной манге Хирому Аракавы, чем более ранняя экранизация 2003 года.","fact":"Первая экранизация 2003 года разошлась с сюжетом манги, поэтому спустя годы студия сняла второй, более точный сериал.","wiki_en":"Fullmetal Alchemist: Brotherhood","wiki_ru":"Стальной алхимик"},{"name":"Евангелион","emoji":"🤖","meta":["меха-аниме","1995–1996","Япония"],"description":"Подростков набирают пилотировать гигантских биомеханических «евангелионов», чтобы противостоять таинственным существам-ангелам, угрожающим человечеству. Под оболочкой меха-боевика сериал скрывает плотную психологическую драму о травмах, одиночестве и страхе близости.","fact":"Финал оригинального сериала оказался настолько нестандартным и абстрактным, что позже студия выпустила альтернативную версию в виде полнометражных фильмов.","wiki_en":"Neon Genesis Evangelion"},{"name":"Инуяша","emoji":"🏹","meta":["сёнэн-аниме","2000–2004","Япония"],"description":"Школьница Кагомэ проваливается сквозь колодец в эпоху Сэнгоку и объединяется с полудемоном Инуясей, чтобы собрать осколки разбитой магической жемчужины Четырёх душ. Сериал снят по манге Румико Такахаси и сочетает приключенческий сюжет с элементами романтики.","fact":"Автор Румико Такахаси известна также как создательница других культовых манга-сериалов, включая «Ранму ½».","wiki_en":"Inuyasha"},{"name":"Ковбой Бибоп","emoji":"🎷","meta":["нео-нуар-аниме","1998–1999","Япония"],"description":"Команда охотников за головами на борту потрёпанного космического корабля «Бибоп» путешествует по Солнечной системе в поисках заработка, а прошлое каждого героя постепенно раскрывается через отдельные, почти самостоятельные серии. Сериал знаменит джазовым саундтреком и кинематографичной режиссурой.","fact":"Музыку к сериалу написала композитор Йоко Канно, а джазовый стиль саундтрека стал неотъемлемой частью его культового статуса.","wiki_en":"Cowboy Bebop"},{"name":"Хантер х Хантер","emoji":"🎣","meta":["сёнэн-аниме","2011–2014","Япония"],"description":"Мальчик Гон Фрикс сдаёт экзамен на звание хантера, чтобы найти пропавшего отца, и на этом пути заводит друзей и сталкивается с противниками, чьи способности подчинены сложной внутренней логике. Сериал 2011 года — более точная и полная экранизация манги Ёсихиро Тогаси.","fact":"Манга-первоисточник печатается с долгими перерывами уже несколько десятилетий из-за проблем со здоровьем автора.","wiki_en":"Hunter × Hunter (2011 TV series)"},{"name":"Магическая битва","emoji":"🌀","meta":["сёнэн-аниме","с 2020","Япония"],"description":"Старшеклассник Юдзи Итадори проглатывает проклятый палец легендарного демона и оказывается втянут в скрытую войну магов-экзорцистов против проклятий, порождённых человеческими негативными эмоциями. Сериал по манге Гэгэ Акутами быстро стал одним из самых заметных аниме конца 2010-х — начала 2020-х.","fact":"У манги есть приквел — короткая серия глав, которую Гэгэ Акутами нарисовал ещё до основной истории.","wiki_en":"Jujutsu Kaisen"},{"name":"Убийца демонов","emoji":"🗡️","meta":["сёнэн-аниме","с 2019","Япония"],"description":"После истребления демоном всей семьи Танджиро Камадо становится охотником на демонов, чтобы найти способ вернуть человеческий облик своей сестре Нэдзуко. Сериал по манге Коёхару Готогэ прославился визуально эффектной анимацией студии ufotable и стал феноменом кассовых сборов в Японии.","fact":"Полнометражные фильмы по мотивам сериала стали одними из самых кассовых в истории японского проката.","wiki_en":"Demon Slayer: Kimetsu no Yaiba"},{"name":"Моя геройская академия","emoji":"💥","meta":["сёнэн-аниме","с 2016","Япония"],"description":"В мире, где почти у всех людей есть сверхспособности, мальчик без единой особенности мечтает стать героем и получает шанс, когда легендарный супергерой передаёт ему свою силу. Сериал по манге Кохэя Хорикоси стал одним из самых успешных представителей жанра супергеройского аниме.","fact":"Автор Кохэй Хорикоси признавался, что на создание сериала его вдохновили американские супергеройские комиксы.","wiki_en":"My Hero Academia"},{"name":"Токийский гуль","emoji":"👹","meta":["сэйнэн-аниме","2014–2018","Япония"],"description":"Обычный студент Кэн Канэки после неудачной операции по трансплантации органов превращается в полугуля, вынужденного балансировать между миром людей и миром существ, питающихся человеческой плотью. Сериал по манге Суи Исиды исследует темы идентичности и отчуждения через мрачную городскую мифологию.","fact":"Из-за расхождений с оригинальной мангой более поздние сезоны сериала вызвали неоднозначную реакцию поклонников первоисточника.","wiki_en":"Tokyo Ghoul"},{"name":"Берсерк","emoji":"⚔️","meta":["сэйнэн-аниме","1997–1998","Япония"],"description":"Одинокий наёмник Гатс, выживший благодаря огромному мечу и собственной ярости, оказывается втянут в тёмную историю предательства и мести на фоне мрачного псевдосредневекового мира. Оригинальный сериал 1997 года по манге Кэнтаро Миуры остаётся одной из самых почитаемых экранизаций дарк-фэнтези.","fact":"Манга-первоисточник Кэнтаро Миуры выходила более тридцати лет и осталась незавершённой после смерти автора в 2021 году.","wiki_en":"Berserk (1997 TV series)"},{"name":"Ранма ½","emoji":"💧","meta":["комедийное аниме","1989–1992","Япония"],"description":"Юный мастер боевых искусств Ранма Саотомэ после падения в проклятый источник превращается в девушку при контакте с холодной водой и обратно — при контакте с горячей. Комедийный сериал по манге Румико Такахаси строится на бесконечной путанице вокруг двойной идентичности героя.","fact":"Проклятие главного героя — лишь одно из множества похожих в сериале: почти у каждого важного персонажа есть собственное превращение.","wiki_en":"Ranma ½"},{"name":"Волейбол!!","emoji":"🏐","meta":["спортивное аниме","2014–2020","Япония"],"description":"Невысокий, но упрямый школьник Сёё Хината мечтает стать выдающимся волейболистом, несмотря на рост, и поступает в команду школы Карасуно вместе со своим главным соперником-партнёром Тобио Кагэямой. Сериал по манге Харуити Фурудатэ известен динамичной прорисовкой матчей и мотивирующим тоном.","fact":"Сериалу приписывают заметный всплеск интереса японских школьников к волейболу и школьным волейбольным секциям.","wiki_en":"Haikyu!!"},{"name":"Призрак в доспехах","emoji":"🌐","meta":["киберпанк-аниме","2002–2005","Япония"],"description":"В будущем, где сознание можно подключать напрямую к сети, майор Мотоко Кусанаги и подразделение девять расследуют киберпреступления на грани философии — где заканчивается человек и начинается машина. Сериал углубляет темы одноимённого фильма 1995 года в формате серийного повествования.","fact":"Название «Синдром одиночки» отсылает к идее сериала: подражатели воспроизводят преступление, у которого не было оригинала.","wiki_en":"Ghost in the Shell: Stand Alone Complex"},{"name":"Гостья из будущего","emoji":"🛸","meta":["фантастика","1985","СССР"],"description":"Школьник Коля Герасимов случайно попадает в Москву будущего и возвращается обратно вместе с девочкой Алисой Селезнёвой, за которой из будущего охотятся космические пираты. Пятисерийный фильм по повести Кира Булычёва стал одним из самых любимых советских фантастических проектов для детей.","fact":"Роль Алисы Селезнёвой сыграла школьница Наталья Гусева, мгновенно ставшая кумиром советских подростков и получавшая мешки писем.","wiki_en":"Guest from the Future","wiki_ru":"Гостья из будущего"},{"name":"Приключения Шерлока Холмса и доктора Ватсона","emoji":"🎩","meta":["детектив","1979–1986","СССР"],"description":"Советский цикл фильмов о сыщике с Бейкер-стрит и его верном друге-докторе считается одной из самых точных и уважаемых экранизаций произведений Артура Конан Дойла. Василий Ливанов и Виталий Соломин создали образы Холмса и Ватсона, ставшие эталонными для нескольких поколений зрителей.","fact":"Василий Ливанов был удостоен ордена Британской империи за исполнение роли Шерлока Холмса — редкий случай признания иностранного актёра.","wiki_en":"The Adventures of Sherlock Holmes and Dr. Watson","wiki_ru":"Приключения Шерлока Холмса и доктора Ватсона (телесериал)"},{"name":"Тени исчезают в полдень","emoji":"🌾","meta":["драма","1971","СССР"],"description":"Многосерийный фильм прослеживает судьбу нескольких поколений жителей сибирской деревни на протяжении советской эпохи — от Гражданской войны до послевоенных лет. Экранизация романа Анатолия Иванова стала одним из первых по-настоящему масштабных советских телесериалов.","fact":"Сериал снят по роману Анатолия Иванова, который также написал книгу, легшую в основу более позднего «Вечного зова».","wiki_en":"Shadows Disappear at Noon","wiki_ru":"Тени исчезают в полдень"},{"name":"Вечный зов","emoji":"🔔","meta":["драма","1973–1983","СССР"],"description":"Многосерийная сага прослеживает судьбу большой сибирской семьи на протяжении полувека российской истории — от начала века до Великой Отечественной войны. Экранизация романа-эпопеи Анатолия Иванова стала одним из самых масштабных советских телесериалов своего времени.","fact":"Съёмки сериала растянулись на добрый десяток лет, а его действие охватывает несколько исторических эпох России XX века.","wiki_en":"Eternal Call","wiki_ru":"Вечный зов (телесериал)"},{"name":"Следствие ведут ЗнаТоКи","emoji":"🕵️","meta":["детектив","1971–1989","СССР"],"description":"Цикл телефильмов о трёх следователях — Знаменском, Томине и Кибрит (сокращённо ЗнаТоКи) — раскрывающих преступления советской милиции. Один из самых долгоживущих и любимых детективных сериалов советского телевидения, выходивший на протяжении почти двух десятилетий.","fact":"Песня «Наша служба и опасна, и трудна», звучавшая в цикле, давно стала неофициальным гимном милиции.","wiki_en":"Investigation Led by Experts","wiki_ru":"Следствие ведут знатоки"},{"name":"Бандитский Петербург","emoji":"🏙️","meta":["криминальная драма","2000–2007","Россия"],"description":"Многосерийный проект по мотивам романов Андрея Константинова показывает становление и войну петербургских криминальных группировок девяностых глазами бандитов, журналистов и следователей. Сериал стал одним из знаковых представителей жанра «бандитского» российского телевидения начала двухтысячных.","fact":"Сериал состоит из нескольких отдельных многосерийных фильмов, объединённых общим миром и частично пересекающимися персонажами.","wiki_en":"Gangster Petersburg","wiki_ru":"Бандитский Петербург (телесериал)"},{"name":"Спрут","emoji":"🐙","meta":["криминальная драма","1984–2001","Италия"],"description":"Комиссар полиции Коррадо Каттани ведёт бескомпромиссную борьбу с сицилийской мафией, чьи щупальца, подобно спруту, дотягиваются до самых верхов власти. Итальянский сериал стал культовым в СССР и постсоветских странах, где массово транслировался в перестроечные годы.","fact":"В Италии сериал шёл под названием La Piovra — «Спрут» — именно из-за метафоры мафии как многощупальцевого чудовища.","wiki_en":"La Piovra"},{"name":"Клон","emoji":"👯","meta":["телесериал","2001–2002","Бразилия"],"description":"Теленовелла переплетает историю запретной любви марокканской девушки Жади и бразильца Лукаса с фантастической линией о тайном клонировании человека. Сочетание восточного колорита, мелодрамы и научной интриги сделало сериал огромным хитом в России начала двухтысячных.","fact":"Название сериала связано с сюжетной линией о создании генетической копии одного из персонажей — редкой темой для теленовелл начала двухтысячных.","wiki_en":"O Clone"},{"name":"Рабыня Изаура","emoji":"⛓️","meta":["телесериал","1976","Бразилия"],"description":"Действие разворачивается на бразильской кофейной плантации XIX века, где красавица-рабыня Изаура становится объектом преследования жестокого хозяина, несмотря на своё тайное благородное происхождение. Экранизация романа Бернарду Гимарайнша стала одной из первых бразильских теленовелл, покоривших советского зрителя.","fact":"В СССР показ сериала в конце восьмидесятых стал культурным событием и одним из первых массовых знакомств зрителя с жанром теленовеллы.","wiki_en":"Escrava Isaura (1976 TV series)","wiki_ru":"Рабыня Изаура (телесериал)"},{"name":"Богатые тоже плачут","emoji":"💔","meta":["телесериал","1979","Мексика"],"description":"Бедная сирота Марианна попадает в дом состоятельной мексиканской семьи, влюбляется в её наследника и проходит через череду мелодраматических испытаний ради своего счастья. Мексиканская теленовелла стала одним из первых зарубежных сериалов, показанных на российском телевидении в начале девяностых, и вызвала настоящий ажиотаж.","fact":"Премьерный показ сериала в России в 1991 году собирал у экранов огромную аудиторию и стал одним из первых массовых телевизионных увлечений постсоветского зрителя.","wiki_en":"Los Ricos También Lloran"},{"name":"Просто Мария","emoji":"🧵","meta":["телесериал","1989","Мексика"],"description":"Скромная швея Мария проходит путь от бедности к успеху и любви, столкнувшись по пути с интригами и предательствами. Мексиканская теленовелла стала одним из культовых зарубежных сериалов для российской аудитории начала девяностых, наравне с «Богатые тоже плачут».","fact":"Имя героини сериала на некоторое время стало нарицательным обозначением жанра латиноамериканской теленовеллы в постсоветской массовой культуре.","wiki_en":"Simplemente María (1989 telenovela)"},{"name":"Улица Сезам","emoji":"🟡","meta":["детская передача","с 1969","США"],"description":"Образовательная программа с куклами-маппетами учит маленьких зрителей буквам, числам и простым жизненным урокам на вымышленной городской улице. Один из самых долгоживущих и влиятельных детских телепроектов в мире, породивший десятки национальных адаптаций, включая российскую «Улицу Сезам».","fact":"Персонажей сериала — маппетов — создал кукольник Джим Хенсон, впоследствии прославившийся также «Маппет-шоу».","wiki_en":"Sesame Street"},{"name":"Ералаш","emoji":"🎬","meta":["киножурнал","с 1974","СССР/Россия"],"description":"Каждый выпуск киножурнала собирает несколько коротких юмористических сюжетов из школьной и детской жизни, часто с неожиданной шуткой в финале. Один из самых долгоживущих проектов отечественного экрана, через который прошли десятки будущих известных актёров в детских ролях.","fact":"Через актёрский состав «Ералаша» за десятилетия прошли сотни детей, многие из которых впоследствии стали известными взрослыми актёрами.","wiki_en":"Yeralash","wiki_ru":"Ералаш (киножурнал)"},{"name":"Кадетство","emoji":"🎖️","meta":["молодёжная драма","2006–2008","Россия"],"description":"Сериал рассказывает о буднях подростков, обучающихся в кадетском корпусе, — их дружбе, первой любви и попытках соответствовать строгой военной дисциплине. Один из заметных российских молодёжных сериалов середины двухтысячных на канале СТС.","fact":"Съёмки сериала проходили с участием консультантов из настоящих кадетских корпусов, чтобы точнее передать атмосферу учебного заведения.","wiki_en":"Kadetstvo","wiki_ru":"Кадетство"},{"name":"Реальные пацаны","emoji":"🎥","meta":["мокьюментари-комедия","с 2010","Россия"],"description":"Сериал снят в формате псевдодокументалистики о буднях простого пермского парня Кольяна и его друзей — с их специфическим юмором, случайными приключениями и почти документальной интонацией. Один из самых успешных долгоиграющих проектов канала ТНТ.","fact":"Действие происходит в Перми, и многие сцены снимали прямо на улицах и во дворах настоящего города.","wiki_en":"Realnye Patsany","wiki_ru":"Реальные пацаны"},{"name":"Молодёжка","emoji":"🏒","meta":["спортивная драма","Россия"],"description":"Сериал о молодой хоккейной команде провинциального города, где спортивные амбиции переплетаются с личными драмами игроков и тренеров. Один из немногих российских сериалов, построивших сюжет вокруг хоккея, и заметный хит канала СТС.","fact":"Хоккейные сцены для сериала снимались с участием консультантов и дублёров из числа настоящих хоккеистов.","wiki_en":"The Junior Team","wiki_ru":"Молодёжка"},{"name":"Ольга","emoji":"🍷","meta":["трагикомедия","2016–2021","Россия"],"description":"Резкая и не самая образцовая мать Ольга пытается разобраться в жизни своей неблагополучной семьи, сочетая чёрный юмор с неожиданно тёплыми моментами. Сериал ТНТ выделяется на фоне типичных ситкомов более смелым и честным тоном.","fact":"Главную роль резкой и языкастой Ольги сыграла актриса Яна Троянова.","wiki_en":"Olga (TV series)","wiki_ru":"Ольга (телесериал)"},{"name":"Тайны следствия","emoji":"🔍","meta":["детектив","с 2000","Россия"],"description":"Следователь прокуратуры Мария Швецова на протяжении множества сезонов расследует самые разные преступления Петербурга, оставаясь одним из самых узнаваемых образов российского детективного телевидения. Сериал остаётся в эфире уже более двух десятилетий, что делает его одним из самых долгоживущих проектов отечественного ТВ.","fact":"Роль Марии Швецовой с самого первого сезона и во всех продолжениях играет актриса Анна Ковальчук.","wiki_en":"Secrets of Investigation","wiki_ru":"Тайны следствия"},{"name":"Содержанки","emoji":"💎","meta":["драма","с 2019","Россия"],"description":"Сериал показывает жизнь нескольких московских женщин, состоящих в отношениях с состоятельными покровителями, и постепенно раскрывает изнанку внешне благополучного мира больших денег. Один из заметных проектов онлайн-платформы Start, получивший известность за откровенность и остросоциальную тематику.","fact":"Сериал стал одним из первых крупных оригинальных проектов российской стриминговой платформы, вышедших за пределы эфирного телевидения.","wiki_en":"Gold Diggers (TV series)","wiki_ru":"Содержанки (сериал)"},{"name":"Дом-2","emoji":"💒","meta":["реалити-шоу","с 2004","Россия"],"description":"Участники живут на закрытой территории и пытаются построить отношения и в перспективе получить собственный дом, а зрители наблюдают за их бытом и конфликтами в почти круглосуточном эфире. Одно из самых долгоживущих реалити-шоу в мире, ставшее заметным явлением российской массовой культуры двухтысячных.","fact":"Ведущими шоу в разные годы были Ксения Собчак и Ксения Бородина, сама начинавшая как участница проекта.","wiki_en":"Dom-2","wiki_ru":"Дом-2"},{"name":"Последний герой","emoji":"🏝️","meta":["реалити-шоу","с 2001","Россия"],"description":"Участники живут на необитаемом острове, соревнуясь в испытаниях и постепенно голосованием исключая друг друга, пока не останется один победитель. Российская адаптация международного формата Survivor стала одним из первых крупных реалити-проектов отечественного телевидения.","fact":"Первые сезоны российской версии вёл актёр Сергей Бодров-младший.","wiki_en":"Last Hero","wiki_ru":"Последний герой (реалити-шоу)"},{"name":"Приключения капитана Врунгеля","emoji":"⛵","meta":["мультсериал","1976–1979","СССР"],"description":"Незадачливый, но обаятельный капитан Врунгель вместе со своей командой отправляется в кругосветное плавание на яхте с говорящим названием, ввязываясь по пути в нелепые и опасные приключения. Советский мультсериал по повести Андрея Некрасова стал классикой отечественной анимации.","fact":"Знаменитая фраза героя о том, что яхту назовёшь — так она и поплывёт, стала крылатым выражением в русском языке.","wiki_en":"Adventures of Captain Wrongel","wiki_ru":"Приключения капитана Врунгеля (мультфильм)"},{"name":"Айкарли","emoji":"💻","meta":["ситком","2007–2012","США"],"description":"Школьница Карли Шей вместе с друзьями ведёт собственное интернет-шоу прямо из своей спальни, попутно переживая типичные подростковые приключения и недоразумения. Сериал канала Nickelodeon одним из первых в мейнстримном ТВ сделал главной темой любительское видеоблогерство.","fact":"Спустя почти десять лет после завершения оригинала сериал получил продолжение с повзрослевшими героями.","wiki_en":"iCarly"},{"name":"Ханна Монтана","emoji":"🎤","meta":["ситком","2006–2011","США"],"description":"Обычная школьница Майли Стюарт ведёт двойную жизнь, скрывая от одноклассников, что на самом деле она — популярная поп-звезда Ханна Монтана. Сериал сделал звездой юную Майли Сайрус и стал одним из флагманских проектов Disney Channel второй половины двухтысячных.","fact":"Главную роль в сериале сыграла Майли Сайрус, дочь кантри-певца Билли Рэя Сайруса, также появлявшегося в шоу.","wiki_en":"Hannah Montana"},{"name":"Волшебники из Вэйверли Плейс","emoji":"✨","meta":["ситком","2007–2012","США"],"description":"Трое детей-волшебников из обычной нью-йоркской семьи тайно осваивают магию, зная, что лишь один из них сможет сохранить силы во взрослом возрасте. Сериал Disney Channel сочетает подростковый ситком с элементами фэнтези и семейного соперничества.","fact":"Главную роль в сериале исполнила Селена Гомес, для которой этот проект стал одним из первых больших актёрских успехов.","wiki_en":"Wizards of Waverly Place"},{"name":"Зои 101","emoji":"🏫","meta":["ситком","2005–2008","США"],"description":"Зои Брукс поступает в престижную школу-интернат, недавно ставшую совместной для мальчиков и девочек, и вместе с друзьями проходит через типичные подростковые перипетии кампусной жизни. Сериал Nickelodeon стал одной из первых крупных актёрских работ Джейми Линн Спирс.","fact":"Главную роль в сериале сыграла Джейми Линн Спирс, младшая сестра певицы Бритни Спирс.","wiki_en":"Zoey 101"},{"name":"Дрейк и Джош","emoji":"🎸","meta":["ситком","2004–2007","США"],"description":"Два очень разных сводных брата — самоуверенный музыкант Дрейк и незадачливый ботаник Джош — вынуждены делить одну комнату и постоянно попадают в комедийные передряги. Сериал Nickelodeon стал одним из самых узнаваемых подростковых ситкомов середины двухтысячных.","fact":"Исполнитель роли Дрейка, Дрейк Белл, также написал и исполнил заглавную песню сериала.","wiki_en":"Drake & Josh"},{"name":"Эй, Арнольд!","emoji":"🏈","meta":["мультсериал","1996–2004","США"],"description":"Добродушный мальчик с необычной формой головы по имени Арнольд живёт с дедушкой и бабушкой в многоквартирном доме большого города и вместе с друзьями переживает истории взросления на фоне узнаваемого городского быта. Сериал Nickelodeon выделяется реалистичным и тёплым взглядом на жизнь городских детей.","fact":"Форма головы главного героя долгие годы оставалась предметом шуток внутри самого сериала, но так и не получила единого объяснения.","wiki_en":"Hey Arnold!","wiki_ru":"Эй, Арнольд!"},{"name":"Ох уж эти детки","emoji":"👶","meta":["мультсериал","1991–2004","США"],"description":"Мир показан глазами компании малышей, которые воспринимают обычные бытовые ситуации как настоящие приключения, полные фантазии и небольших опасностей. Один из самых успешных мультсериалов Nickelodeon девяностых, ставший визитной карточкой канала.","fact":"Зритель прекрасно понимает речь малышей, а взрослые слышат от них лишь лепет — на этом построена половина шуток сериала.","wiki_en":"Rugrats"},{"name":"Дикая семейка Торнберри","emoji":"🦁","meta":["мультсериал","1998–2004","США"],"description":"Дочь путешествующих документалистов Элиза Торнберри получает волшебную способность разговаривать с животными и использует её, помогая живой природе во время семейных экспедиций по всему миру. Сериал Nickelodeon сочетает приключенческий сюжет с образовательными темами об экологии.","fact":"Способность героини говорить с животными сериал объясняет вмешательством таинственного духа природы, встреченного ею в Африке.","wiki_en":"The Wild Thornberrys"},{"name":"Финес и Ферб","emoji":"🛠️","meta":["мультсериал","2007–2015","США"],"description":"Два неугомонных сводных брата каждый день лета придумывают и строят невероятные изобретения, пока их старшая сестра безуспешно пытается разоблачить их перед родителями. Сериал Disney Channel построен на повторяющейся структуре серий и стал одним из самых любимых зрителями мультпроектов канала.","fact":"Почти в каждой серии есть фраза про то, куда делся Перри — домашний питомец героев, который на самом деле тайный агент.","wiki_en":"Phineas and Ferb"},{"name":"Леди Баг и Супер-Кот","emoji":"🐞","meta":["анимационный супергеройский сериал","с 2015","Франция"],"description":"Парижские школьники Маринетт и Адриан тайно превращаются в супергероев Леди Баг и Супер-Кота, чтобы противостоять злодею, охотящемуся за их волшебными артефактами, при этом не подозревая о настоящих личностях друг друга под маской. Французский мультсериал получил широкую международную популярность, включая заметный успех в России.","fact":"Создатель сериала Томас Астрюк признавался, что вдохновлялся классическими супергеройскими комиксами и японскими махо-сёдзё одновременно.","wiki_en":"Miraculous: Tales of Ladybug & Cat Noir"},{"name":"Наруто: Ураганные хроники","emoji":"🍥","meta":["сёнэн-аниме","2007–2017","Япония"],"description":"Продолжение истории ниндзя Наруто Удзумаки показывает его взросление и путь к тому, чтобы стать сильнейшим и самым уважаемым ниндзя своей деревни, вопреки печати опасного духа, запечатанного в нём с рождения. Сериал — прямое продолжение оригинального «Наруто» и один из самых узнаваемых сёнэн-тайтлов в мире.","fact":"Общая продолжительность «Наруто» вместе с «Ураганными хрониками» превышает семьсот серий.","wiki_en":"Naruto: Shippuden"},{"name":"Блич","emoji":"💀","meta":["сёнэн-аниме","2004–2012","Япония"],"description":"Обычный школьник Итиго Куросаки получает силы синигами — проводника душ — и берёт на себя обязанность защищать живых и мёртвых от злых духов. Сериал по манге Тайто Кубо известен яркими сражениями и запоминающимся дизайном персонажей.","fact":"После долгого перерыва сериал получил продолжение в 2022 году, экранизирующее финальную арку манги.","wiki_en":"Bleach (TV series)","wiki_ru":"Блич"},{"name":"Ванпанчмен","emoji":"👊","meta":["пародийное аниме","с 2015","Япония"],"description":"Герой Сайтама настолько силён, что побеждает любого противника одним ударом, и от этого его главной проблемой становится не сражение со злом, а обычная скука. Сериал по вебкомиксу Оне пародирует штампы супергеройского жанра, оставаясь при этом зрелищным экшеном.","fact":"Изначально «Ванпанчмен» существовал как любительский веб-комикс автора под псевдонимом Оне, ставший вирусным ещё до профессиональной публикации.","wiki_en":"One-Punch Man"},{"name":"Пространство","emoji":"🛰️","meta":["научная фантастика","2015–2022","США"],"description":"В будущем, где человечество расселилось по Солнечной системе, политическое напряжение между Землёй, Марсом и поясом астероидов перерастает в масштабный конфликт после загадочной находки. Сериал снят по циклу романов Джеймса Кори и славится тщательно продуманной научной достоверностью.","fact":"Сериал был закрыт телеканалом SyFy после третьего сезона, но продолжен благодаря выкупу прав платформой Amazon.","wiki_en":"The Expanse (TV series)","wiki_ru":"Пространство (телесериал)"},{"name":"Тьма","emoji":"🌑","meta":["научно-фантастическая драма","2017–2020","Германия"],"description":"Исчезновение детей в маленьком немецком городке приводит к раскрытию тайны, связывающей несколько поколений местных семей через петли времени. Немецкий сериал Netflix известен сложной, тщательно выстроенной структурой повествования и мрачной атмосферой.","fact":"Это был первый оригинальный немецкоязычный сериал, выпущенный Netflix.","wiki_en":"Dark (TV series)","wiki_ru":"Тьма (телесериал)"},{"name":"Видящий","emoji":"🌫️","meta":["научная фантастика","2019–2022","США"],"description":"В далёком будущем вирус лишил почти всё человечество зрения, а рождение детей, способных видеть, становится источником страха и религиозного трепета. Сериал с Джейсоном Момоа в главной роли исследует, как устроено общество, полностью адаптировавшееся к жизни без зрения.","fact":"Для более достоверного изображения слепоты создатели консультировались со специалистами и незрячими консультантами.","wiki_en":"See (TV series)"},{"name":"Хорошая жена","emoji":"👩‍⚖️","meta":["юридическая драма","2009–2016","США"],"description":"После публичного скандала с мужем-политиком Алисия Флоррик возвращается к профессии юриста, чтобы обеспечить семью и заново выстроить собственную жизнь и карьеру. Сериал сочетает формат «дело за серию» с долгоиграющей политической и личной драмой.","fact":"Сюжет сериала во многом вдохновлён реальными политическими скандалами, связанными с изменами публичных фигур.","wiki_en":"The Good Wife","wiki_ru":"Хорошая жена (телесериал)"},{"name":"Как избежать наказания за убийство","emoji":"🖤","meta":["юридический триллер","2014–2020","США"],"description":"Харизматичная и беспощадная преподавательница права Аннализ Китинг вовлекает группу своих студентов в клубок из реальных судебных дел и собственных тёмных тайн. Сериал известен нелинейным повествованием, перемешивающим настоящее и будущее внутри одного сезона.","fact":"Главную роль исполнила Вайола Дэвис, ставшая первой темнокожей актрисой, получившей премию «Эмми» за главную драматическую роль.","wiki_en":"How to Get Away with Murder"},{"name":"Миллиарды","emoji":"💰","meta":["драма","2016–2023","США"],"description":"Амбициозный прокурор Чак Роудс вступает в затяжное противостояние с влиятельным управляющим хедж-фондом Бобби Аксельродом, превращая борьбу с финансовыми махинациями в личную вендетту. Сериал показывает мир Уолл-стрит изнутри — через власть, деньги и бескомпромиссные амбиции.","fact":"Прокурора Чака Роудса играет Пол Джаматти, а миллиардера Бобби Аксельрода — Дэмиэн Льюис.","wiki_en":"Billions (TV series)"},{"name":"Государственная граница","emoji":"🪖","meta":["военная драма","1980–1988","СССР"],"description":"Цикл многосерийных фильмов рассказывает о защитниках советской государственной границы в разные исторические периоды — от революции до послевоенных лет. Один из самых масштабных советских телепроектов о пограничниках, снятый в нескольких отдельных фильмах-эпизодах общего цикла.","fact":"Все фильмы цикла снимала белорусская киностудия «Беларусьфильм».","wiki_en":"State Border","wiki_ru":"Государственная граница (телесериал)"},{"name":"Каменская","emoji":"🔎","meta":["детектив","1999–2011","Россия"],"description":"Сотрудница уголовного розыска Анастасия Каменская, умная и внешне неприметная женщина, раскрывает сложные преступления скорее интеллектом и аналитическим складом ума, чем силой. Сериал снят по циклу детективных романов Александры Марининой и стал одним из знаковых российских детективных проектов рубежа веков.","fact":"Автор книг-первоисточников Александра Маринина сама много лет прослужила в милиции.","wiki_en":"Kamenskaya (TV series)","wiki_ru":"Каменская (телесериал)"},{"name":"Убойная сила","emoji":"🔫","meta":["криминальная драма","2000–2005","Россия"],"description":"Сериал следит за буднями сотрудников убойного отдела петербургской милиции, расследующих самые тяжкие преступления девяностых и двухтысячных. Один из знаковых российских криминальных сериалов начала двухтысячных, продолжающий линию отечественного «милицейского» детектива.","fact":"Сериал снимался в Санкт-Петербурге и во многом опирался на реальную практику работы уголовного розыска того времени.","wiki_en":"Deadly Force (TV series)","wiki_ru":"Убойная сила"},{"name":"Воронины","emoji":"🏠","meta":["ситком","2009–2019","Россия"],"description":"Большая и шумная семья Ворониных из трёх поколений делит одну квартиру, постоянно ссорясь и мирясь по мелким бытовым поводам. Российская адаптация американского ситкома «Все любят Реймонда» стала одним из самых долгоживущих проектов канала СТС.","fact":"Костю Воронина все сезоны играет Георгий Дронов, а его жену Веру — Екатерина Волкова.","wiki_en":"Voronin's Family","wiki_ru":"Воронины (телесериал)"},{"name":"Счастливы вместе","emoji":"👞","meta":["ситком","2006–2013","Россия"],"description":"Продавец обуви Гена Букин мечтает о лучшей жизни, но застревает в шумной и не всегда взаимопонимающей семье в маленьком провинциальном городе. Российская адаптация американского ситкома «Женаты... с детьми» стала одним из главных хитов раннего эфира ТНТ.","fact":"Сериал — официальная российская адаптация американского ситкома «Женаты... с детьми».","wiki_en":"Happy Together (Russian TV series)","wiki_ru":"Счастливы вместе (телесериал)"},{"name":"6 кадров","emoji":"🎭","meta":["скетч-шоу","2006–2014","Россия"],"description":"Каждый выпуск собирает несколько коротких комедийных скетчей с постоянной труппой актёров, разыгрывающих узнаваемые бытовые ситуации, доведённые до абсурда. Один из самых заметных скетч-проектов российского телевидения двухтысячных на канале СТС.","fact":"Название шоу отсылает к идее, что законченную смешную сценку можно рассказать всего за несколько кадров-эпизодов.","wiki_en":"6 kadrov","wiki_ru":"6 кадров"},{"name":"Наша Russia","emoji":"🎪","meta":["скетч-шоу","2006–2009","Россия"],"description":"Скетч-шоу представляет галерею гротескных персонажей из разных уголков России — от гастарбайтеров до охранников, — высмеивая узнаваемые социальные типажи и стереотипы. Шоу стало одним из заметных развлекательных проектов канала ТНТ второй половины двухтысячных.","fact":"Формат шоу во многом вдохновлён британским скетч-проектом «Little Britain», адаптированным для российских реалий.","wiki_en":"Nasha Russia","wiki_ru":"Наша Russia"},{"name":"Даёшь молодёжь!","emoji":"🎊","meta":["скетч-шоу","2006–2010","Россия"],"description":"Скетч-шоу с постоянным составом молодых актёров разыгрывает короткие юмористические зарисовки на темы студенческой и молодёжной жизни. Один из заметных развлекательных проектов канала СТС второй половины двухтысячных.","fact":"Через актёрский состав шоу прошли несколько исполнителей, впоследствии ставших заметными фигурами российского юмористического телевидения.","wiki_en":"Dayosh Molodyozh!","wiki_ru":"Даёшь молодёжь!"},{"name":"Жуки","emoji":"🪲","meta":["комедия","2019–2023","Россия"],"description":"Трое друзей из провинциального городка неожиданно получают в наследство обанкротившийся завод и пытаются превратить его в успешный бизнес, несмотря на полное отсутствие опыта. Сериал сочетает лёгкую комедию с тёплой историей о дружбе и взрослении.","fact":"Первый сезон сериала вышел на YouTube-канале, прежде чем шоу закрепилось на платформе PREMIER.","wiki_en":"Zhuki (TV series)","wiki_ru":"Жуки (телесериал)"},{"name":"Триггер","emoji":"💢","meta":["драма","2018–2020","Россия"],"description":"Психотерапевт Артём Стрелецкий применяет провокационные и нестандартные методы лечения, буквально выводя пациентов из равновесия ради их же исцеления. Сериал Первого канала поднимает темы психологии и травмы для широкой аудитории федерального телевидения.","fact":"Методы главного героя основаны на реальном направлении психотерапии — провокативной терапии, использующей нестандартные приёмы.","wiki_en":"Trigger (Russian TV series)","wiki_ru":"Триггер (телесериал)"},{"name":"Твин Пикс: Возвращение","emoji":"🦉","meta":["мистическая драма","2017","США"],"description":"Спустя четверть века после оригинального сериала Дэвид Линч возвращается к истории городка Твин-Пикс новым, ещё более сюрреалистичным и экспериментальным сезоном. Третий сезон культового сериала снят как единый многочасовой авторский фильм.","fact":"Все восемнадцать серий сезона поставил лично Дэвид Линч, что для телевизионного проекта такого масштаба большая редкость.","wiki_en":"Twin Peaks: The Return"},{"name":"Все любят Реймонда","emoji":"🍝","meta":["ситком","1996–2005","США"],"description":"Спортивный журналист Рэймонд Барон пытается сохранить мир в семье, живя буквально через дорогу от родителей, которые вмешиваются в каждую мелочь его жизни. Один из самых успешных американских ситкомов рубежа веков, удостоенный множества премий «Эмми».","fact":"Сериал лёг в основу нескольких международных адаптаций, включая российский сериал «Воронины».","wiki_en":"Everybody Loves Raymond"},{"name":"Розанна","emoji":"👩‍👧‍👦","meta":["ситком","1988–1997","США"],"description":"Сериал показывает жизнь рабочей семьи Коннер из провинциального Иллинойса без привычной для ситкомов идеализации — с финансовыми трудностями и бытовыми конфликтами. Шоу Розанны Барр одним из первых на американском телевидении честно говорило о жизни небогатого рабочего класса.","fact":"Спустя более двадцати лет после финала сериал получил возрождение в 2018 году с прежним основным актёрским составом.","wiki_en":"Roseanne","wiki_ru":"Розанна (телесериал)"},{"name":"Шоу Косби","emoji":"👨‍👩‍👧‍👦","meta":["ситком","1984–1992","США"],"description":"Сериал о благополучной чернокожей семье среднего класса — враче-гинекологе Клиффе Хакстейбле, его жене-адвокату и пятерых детях — стал одним из самых рейтинговых американских ситкомов восьмидесятых. Шоу во многом изменило телевизионное изображение чернокожей семьи в массовой культуре США.","fact":"На пике популярности сериал на протяжении нескольких сезонов подряд оставался самым рейтинговым шоу американского телевидения.","wiki_en":"The Cosby Show"},{"name":"Даллас","emoji":"🤠","meta":["драма","1978–1991","США"],"description":"Сериал показывает интриги и семейные конфликты богатой техасской нефтяной династии Юингов — с изменами, предательствами и борьбой за бизнес-империю. Один из самых успешных прайм-тайм сериалов восьмидесятых, породивший жанровую моду на «мыльные оперы» о богатых семьях.","fact":"Сюжетный поворот с воскрешением персонажа, объяснённый тем, что целый сезон оказался лишь сном героини, стал одним из самых обсуждаемых приёмов в истории телевидения.","wiki_en":"Dallas (1978 TV series)"},{"name":"Династия","emoji":"👑","meta":["драма","1981–1989","США"],"description":"Сериал о богатой денверской семье нефтяных магнатов Кэррингтонов, чьи внутренние распри и роскошный образ жизни стали образцом жанра прайм-тайм-мелодрамы восьмидесятых. Шоу известно эффектными нарядами и одним из самых узнаваемых женских противостояний на телевидении той эпохи.","fact":"Костюмы сериала во многом задали моду на объёмные плечи и роскошный гардероб, ассоциирующийся с эстетикой восьмидесятых.","wiki_en":"Dynasty (1981 TV series)"},{"name":"Беверли-Хиллз, 90210","emoji":"🌴","meta":["подростковая драма","1990–2000","США"],"description":"Сериал следит за жизнью группы учеников привилегированной школы богатого района Лос-Анджелеса — с их романами, дружбой и взрослением на фоне роскоши. Один из первых по-настоящему успешных молодёжных драматических сериалов, задавших моду на жанр на десятилетия вперёд.","fact":"Название сериала происходит от реального почтового индекса района Беверли-Хиллз — 90210.","wiki_en":"Beverly Hills, 90210"},{"name":"Мелроуз-Плейс","emoji":"🏢","meta":["драма","1992–1999","США"],"description":"Сериал-спин-офф «Беверли-Хиллз, 90210» показывает жизнь группы молодых взрослых, снимающих квартиры в одном жилом комплексе Лос-Анджелеса, — с романами, изменами и профессиональными амбициями. Шоу стало одним из главных представителей жанра прайм-тайм-мелодрамы девяностых.","fact":"Сериал изначально задумывался как более спокойная реалистичная драма, но со временем стал куда более мелодраматичным и эксцентричным.","wiki_en":"Melrose Place"},{"name":"Дикий ангел","emoji":"💃","meta":["теленовелла","1998–1999","Аргентина"],"description":"Скромная девушка из бедного квартала по имени Милагрос попадает в мир богатой аргентинской семьи, где сталкивается с интригами и находит настоящую любовь. Аргентинская теленовелла с юной Натальей Орейро в главной роли получила широкую популярность далеко за пределами Латинской Америки, включая Россию.","fact":"Главная песня сериала в исполнении Натальи Орейро стала настоящим музыкальным хитом далеко за пределами Аргентины.","wiki_en":"Muñeca Brava"},{"name":"Семь смертных грехов","emoji":"🍺","meta":["фэнтези-аниме","2014–2021","Япония"],"description":"Группа некогда прославленных, а затем оклеветанных рыцарей по прозвищу «Семь смертных грехов» вновь объединяется, чтобы спасти королевство от заговора и вернуть себе доброе имя. Сериал по манге Накабы Судзуки сочетает приключенческое фэнтези с элементами юмора и романтики.","fact":"Каждый из семи главных героев сериала ассоциируется с одним из библейских смертных грехов, отражающим черту его характера.","wiki_en":"The Seven Deadly Sins (manga)","wiki_ru":"Семь смертных грехов (манга)"},{"name":"Что мы делаем в тени","emoji":"🧛","meta":["комедия","2019–2024","США"],"description":"Четверо вампиров-соседей, живущих на Стейтен-Айленде, снимаются для псевдодокументального фильма о своём вечном, но на удивление скучном и бытовом бессмертии. Сериал-спин-офф одноимённого новозеландского фильма 2014 года сохранил мокьюментари-формат оригинала.","fact":"Сериал основан на фильме 2014 года режиссёров Тайки Вайтити и Джемейна Клемента, выступивших и продюсерами сериала.","wiki_en":"What We Do in the Shadows (TV series)"},{"name":"Могучие рейнджеры","emoji":"🦸","meta":["супергеройский экшен","1993–1996","США"],"description":"Пятеро обычных подростков получают от инопланетного наставника способности превращаться в разноцветных супергероев-рейнджеров, чтобы защищать Землю от космических злодеев. Сериал стал одним из самых узнаваемых франшизных проектов девяностых благодаря сочетанию американских актёрских сцен с японскими кадрами боёв из «Super Sentai».","fact":"Экшен-сцены сериала смонтированы из отснятого материала японского сериала «Super Sentai», адаптированного под американский сюжет.","wiki_en":"Mighty Morphin Power Rangers"},{"name":"Универ. Новая общага","emoji":"🛏️","meta":["ситком","2011–2018","Россия"],"description":"Сериал-спин-офф «Универа» переносит зрителя в студенческое общежитие, где новое поколение персонажей проходит через комедийные ситуации студенческого быта и отношений. Один из долгоживущих флагманских ситкомов канала ТНТ двухтысячных и десятых.","fact":"Сериал является продолжением более раннего проекта «Универ», действие которого происходило несколькими годами ранее.","wiki_en":"Univer. New Dorm","wiki_ru":"Универ. Новая общага"},{"name":"Домашний арест","emoji":"🏠","meta":["сатирическая комедия","2018","Россия"],"description":"Молодой провинциальный блогер случайно провоцирует политический скандал своим резким видео о коррупции местных властей и оказывается под домашним арестом, откуда наблюдает за абсурдной реакцией чиновников. Сериал сочетает политическую сатиру с комедией положений.","fact":"Сериал вышел на стриминговой платформе и известен нестандартно резкой для российского телевидения политической сатирой.","wiki_en":"House Arrest (Russian TV series)","wiki_ru":"Домашний арест (телесериал)"},{"name":"Звоните ДиКаприо!","emoji":"📱","meta":["драма","2018","Россия"],"description":"Молодой актёр, недавно шагнувший к успеху, узнаёт о собственном ВИЧ-положительном статусе и вынужден заново пересмотреть отношение к карьере, близким и самому себе. Российская мини-серия одной из первых на отечественном телевидении открыто и без стигматизации подняла тему жизни с ВИЧ.","fact":"Сериал получил признание за редкое для российского телевидения деликатное и без осуждения освещение темы ВИЧ.","wiki_en":"Call DiCaprio!","wiki_ru":"Звоните ДиКаприо!"},{"name":"Чики","emoji":"👭","meta":["драма","2018–2021","Украина/Россия"],"description":"Сериал показывает жизнь группы девушек в женской исправительной колонии — их дружбу, конфликты и попытки сохранить себя в жёстких условиях заключения. Проект стриминговой платформы Start получил известность за честный и не приукрашенный взгляд на женскую тюремную среду.","fact":"Съёмки сериала проходили с консультациями людей, знакомых с реальным бытом исправительных учреждений, ради большей достоверности.","wiki_en":"Chiki (TV series)","wiki_ru":"Чики (телесериал)"},{"name":"Эмили в Париже","emoji":"🥐","meta":["романтическая комедия","с 2020","США"],"description":"Американская специалистка по маркетингу Эмили Купер неожиданно переезжает работать в Париж и пытается совместить французскую элегантность с американским трудовым энтузиазмом, попутно переживая череду романтических увлечений. Сериал Netflix известен яркой картинкой и модными нарядами героини.","fact":"Съёмки сериала проходят преимущественно в реальных узнаваемых локациях Парижа, что стало частью его визуальной привлекательности.","wiki_en":"Emily in Paris"},{"name":"Полиция Гавайев","emoji":"🌺","meta":["криминальная драма","2010–2020","США"],"description":"Специальное подразделение полиции штата Гавайи во главе с детективом Стивом МакГарреттом расследует самые сложные преступления острова — от контрабанды до терроризма. Современный сериал — перезапуск одноимённого детективного шоу конца шестидесятых, сохранивший узнаваемую заставку и главную тему.","fact":"Музыкальная заставка сериала — практически без изменений унаследованная от оригинального шоу 1968 года — считается одной из самых узнаваемых в истории телевидения.","wiki_en":"Hawaii Five-0 (2010 TV series)"},{"name":"C.S.I.: Нью-Йорк","emoji":"🗽","meta":["криминальная драма","2004–2013","США"],"description":"Ещё один спин-офф оригинального «C.S.I.» переносит команду криминалистов в Нью-Йорк, где во главе расследований стоит детектив Мак Тейлор, переживший теракт 11 сентября. Сериал сохранил формат франшизы, добавив нью-йоркский колорит и более личную драму главного героя.","fact":"Предыстория главного героя сериала связана с потерей жены во время теракта 11 сентября 2001 года.","wiki_en":"CSI: NY"},{"name":"Она написала убийство","emoji":"✍️","meta":["детектив","1984–1996","США"],"description":"Писательница детективных романов и по совместительству любительский сыщик Джессика Флетчер регулярно оказывается рядом с местом преступления в своём тихом городке и раскрывает его быстрее профессиональной полиции. Один из самых долгоживущих детективных сериалов американского телевидения восьмидесятых-девяностых.","fact":"Несмотря на добродушный образ героини, за все сезоны сериала она оказалась свидетельницей нескольких сотен убийств — этот парадокс стал предметом постоянных шуток зрителей.","wiki_en":"Murder, She Wrote","wiki_ru":"Она написала убийство"},{"name":"МакГайвер","emoji":"🧰","meta":["приключенческий боевик","1985–1992","США"],"description":"Секретный агент Ангус МакГайвер решает самые опасные ситуации не силой оружия, а изобретательностью, собирая хитроумные устройства буквально из подручных предметов. Сериал сделал слово «макгайверить» нарицательным обозначением находчивого самодельного решения проблем.","fact":"Фамилия героя стала нарицательным глаголом macgyver, обозначающим находчивое решение проблемы подручными средствами.","wiki_en":"MacGyver (1985 TV series)"},{"name":"Полиция Майами: Отдел нравов","emoji":"🌴","meta":["криминальная драма","1984–1990","США"],"description":"Два детектива под прикрытием в солнечном Майами расследуют наркоторговлю и организованную преступность, сочетая опасную работу с ярким визуальным стилем восьмидесятых — пастельными костюмами и стремительными катерами. Сериал во многом определил эстетику целого десятилетия на телевидении.","fact":"Фирменный стиль сериала — пастельные костюмы без носков и неоновая эстетика — оказал заметное влияние на моду восьмидесятых.","wiki_en":"Miami Vice"},{"name":"Зена — королева воинов","emoji":"🗡️","meta":["фэнтези-экшен","1995–2001","США"],"description":"Бывшая воительница с тёмным прошлым Зена странствует по мифологическому миру Древней Греции вместе с верной спутницей Габриэль, сражаясь за искупление былых грехов. Сериал стал одним из знаковых проектов синдицированного телевидения девяностых и культовой фигурой поп-культуры для многих поколений зрительниц.","fact":"Персонаж Зены впервые появился как второстепенный герой в сериале «Удивительные странствия Геракла», прежде чем получить собственное шоу.","wiki_en":"Xena: Warrior Princess"}];
